        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["ui.terminusNone"]="Für diese Linie ist keine Endhaltestelle festgelegt, daher ist der Fahrplan an der ersten Haltestelle der Strecke verankert. Wähle eine Haltestelle, die diese Linie bedient, und lege sie als Endhaltestelle fest, um zu bestimmen, wo die Fahrzeuge auf ihre Abfahrt warten.", ["ui.terminusLost"]="Die Endhaltestelle dieser Linie liegt nicht mehr auf ihrer Strecke, daher greift der Fahrplan nun auf die erste Haltestelle zurück. Wähle eine Haltestelle, die diese Linie bedient, und lege sie als Endhaltestelle fest.", ["opt.ManageVehicleCount.L"]="Fahrzeuganzahl verwalten", ["opt.ManageVehicleCount.D"]="Wenn aktiviert (Standard), legt die Mod die Fahrzeuganzahl jeder Linie mit Fahrplan so fest, dass dein gewählter Taktabstand eingehalten wird. Deaktiviere die Option, um die Fahrzeuganzahl dir selbst oder einer anderen Flotten-Mod (wie All Transit + Truck) zu überlassen – die Mod hält Abfahrten weiterhin an der Endstation zurück, sie fügt nur keine Busse hinzu und ändert keine. Eine Linie mit zu wenigen Fahrzeugen fährt dann einfach in größeren Abständen als eingestellt.", ["opt.CleanUninstall.L"]="Alle Mod-Daten aus diesem Spielstand entfernen", ["opt.CleanUninstall.W"]="Dies LÖSCHT den Fahrplan jeder Linie in dieser Stadt und setzt alle Linien auf das Verhalten des Basisspiels zurück. Deine linienbezogenen Abfahrtszeiten, eigenen Spitzenfenster und gemessenen Fahrzeitdaten gehen verloren und können nicht wiederhergestellt werden.\n\nWICHTIG: Schließe nach dem Bestätigen dieses Menü, lass das Spiel einen Moment LAUFEN und speichere dann. Die Bereinigung erfolgt erst im nächsten Simulationsschritt; speicherst du im pausierten Zustand, bleibt deine Stadt also unverändert.\n\nFortfahren?", ["opt.CleanUninstall.D"]="Einmalige Bereinigung für eine saubere Deinstallation. Setzt jede Linie auf Vanilla zurück (gibt gehaltene Busse frei, stellt den Entklumpungsfaktor wieder her, verwirft die vom Mod gesetzte Fahrzeuganzahl) und entfernt die gespeicherten Daten des Mods aus dieser Stadt (deine linienbezogenen Fahrpläne, eigenen Spitzenzeiten und gemessenen Fahrzeitdaten). Drücke die Schaltfläche, lass dann das Spiel einen Moment laufen (die Bereinigung erfolgt im nächsten Simulationsschritt, im pausierten Zustand passiert also nichts) und SPEICHERE danach — anschließend kann der Mod ohne Rückstände entfernt werden. Dabei werden deine Fahrpläne gelöscht, daher wird vorher um Bestätigung gebeten. Unschädlich, wenn du sie bei weiterhin installiertem Mod drückst — die Linien kehren dann einfach zum reinen Vanilla-Verhalten zurück.", ["opt.MaxDwellRoad.L"]="Maximale Haltezeit — Busse (Minuten über die Abfahrtszeit hinaus)", ["opt.MaxDwellRoad.D"]="Wie lange ein Bus über seine planmäßige Abfahrt hinaus auf Fahrgäste warten darf, die BEREITS einsteigen. Es ist eine Obergrenze, kein Zielwert: Ein Bus, bei dem niemand einsteigt, fährt trotzdem exakt zu seiner planmäßigen Minute ab, und diese Einstellung verzögert ihn keine Sekunde. Es gibt diese Einstellung, weil das Basisspiel jemanden schon in dem Moment als Fahrgast zählt, in dem er zum Fahrzeug zu laufen beginnt — eine harte Abfahrt würde also alle, die noch quer über die Haltestelle zum Fahrzeug laufen, zurück in die Warteschlange werfen. Nun wartet das Fahrzeug auf sie, aber nie länger als diesen Wert. Standard: 3 Minuten. Setze ihn auf 0, um auf die Minute genau abzufahren und auf niemanden zu warten. Hinweis: Das funktioniert, indem das spieleigene Einstiegsfenster verkürzt wird; ein Fahrzeug kann dadurch nie LÄNGER warten, als das Spiel es ohnehin täte — und wenn du einen Mod nutzt, der den Spieltag verlängert, sind die höchsten Werte hier möglicherweise nicht erreichbar.", ["opt.MaxDwellRail.L"]="Maximale Haltezeit — Züge, U-Bahnen und Straßenbahnen (Minuten über die Abfahrtszeit hinaus)", ["opt.MaxDwellRail.D"]="Dieselbe Obergrenze für die Schiene, ebenfalls standardmäßig 3 Minuten. Erhöhe sie, wenn du siehst, wie sich auf einem stark frequentierten Bahnsteig die Fahrgäste stauen: Züge und U-Bahnen, die einen ganzen Bahnsteig voller Fahrgäste austauschen, brauchen zum Einsteigen weit länger als ein Bus, ihre Fahrgäste verteilen sich über den Bahnsteig, um ihren eigenen Wagen zu erreichen, und anders als ein Bus können sie eine Station nie überspringen. Bedenke, dass diese Zusatzzeit an jeder Station gilt: Ein großzügiger Wert summiert sich auf einer langen Linie also über den gesamten Umlauf — und längere Haltezeiten bedeuten einen längeren echten Umlauf, sodass die Linie mehr Fahrzeuge braucht, um denselben Takt zu halten. Wie beim Wert für Busse verkürzt dies das spieleigene Einstiegsfenster, statt es zu verlängern; unter einem Zeitlupen-Mod sind die höchsten Werte daher möglicherweise nicht erreichbar.", ["opt.RealisticTravelTime.L"]="Realistische Fahrzeit (korrigiert angezeigte Zeiten)", ["opt.RealisticTravelTime.D"]="Die spieleigene Schätzung, wie lange eine Linie braucht, liegt unter dem echten, simulierten Umlauf — Busse beschleunigen und bremsen an jeder Haltestelle, was die Schätzung ignoriert (live gemessen etwa 1,7x auf dünnen Linien bis ~2,5x auf haltestellendichten). Aktiviere dies, und der Mod misst den echten Umlauf jeder Linie und trägt realistische Haltezeiten ein, sodass der Fahrplan dem entspricht, was die Busse tatsächlich tun. Kostet nichts — es macht die Uhr nur ehrlich. Standardmäßig AUS; bestehende Fahrpläne bleiben unverändert, bis du es aktivierst.", ["opt.ProvisionRealFleet.L"]="Fuhrpark an reale Fahrzeit anpassen (erhöht die Fahrzeuganzahl)", ["opt.ProvisionRealFleet.D"]="Bemisst außerdem die Fahrzeuganzahl jeder Linie an ihrem ECHTEN Umlauf statt an der Schätzung. Dies ist die Option, die Geld kostet: einen engen Takt auf einer Linie zu halten, deren echter Umlauf ~2x der Schätzung beträgt, benötigt etwa doppelt so viele Fahrzeuge und doppelten Unterhalt. AUS (Standard) behält die schätzungsbasierte Anzahl, sodass eine Linie unbemerkt einen längeren effektiven Takt fährt als eingestellt; AN legt für den echten Umlauf aus. Nur aufstockend — es senkt eine Linie nie unter die Schätzung — und begrenzt, damit eine fehlerhafte Messung dich nicht mit Bussen überflutet.", ["ui.vehNotOnTimetable"]="Noch nicht im Fahrplan. Das Fahrzeug übernimmt seinen Fahrplan, sobald es zum ersten Mal die Endhaltestelle erreicht.", ["ui.vehHolding"]="Wartet hier bis {at}, der planmäßigen Abfahrt.", ["ui.vehAtStopLate"]="An dieser Haltestelle, {n} Min. hinter der Abfahrt um {at}.", ["ui.vehAtStop"]="An dieser Haltestelle, Abfahrt um {at}.", ["ui.vehNextStop"]="Nächster Halt planmäßig um {at}.", ["ui.vehBehind"]="{n} Min. hinter dem Fahrplan. Der nächste Halt war für {at} vorgesehen.", ["ui.vehRefining"]="Diese Linie misst noch ihre tatsächliche Umlaufzeit, daher werden sich diese Zeiten noch ändern.", ["ui.rttOffWarning"]="Realistische Fahrzeit ist AUS, daher verwenden die angezeigten Zeiten die Schätzung des Spiels statt dieser gemessenen Umlaufzeit. Aktiviere sie in den Optionen des Mods, um die gemessenen Zeiten zu verwenden.", ["ui.loopMeasuring"]="Die tatsächliche Umlaufzeit wird noch gemessen ({laps} von {need} Runden).", ["ui.loopRefining"]="Tatsächliche Umlaufzeit etwa {real} Min., wird noch verfeinert ({wlaps} von {need2} Runden).", ["ui.loopMeasured"]="Tatsächliche Umlaufzeit {real} Min., gemessen ({corr}x der Schätzung von {est} Min.).", ["ui.countMayRise"]="Diese Anzahl ist bewusst vorsichtig gewählt und kann steigen, sobald die Messung abgeschlossen ist.", ["ui.sizingSoon"]="Diese Linie wird bemessen, sobald ihre Fahrzeitschätzung stabil ist.", ["ui.notSetByMod"]="Dieser Takt benötigt ca. {n} Fahrzeuge. Dieser Mod legt die Anzahl nicht fest.", ["ui.provisioning"]="Dafür werden ca. {n} Fahrzeuge bereitgestellt.", ["ui.realLoopEstimated"]="Echter Umlauf ca. {real} Min ({corr}x der {est}-Min-Schätzung, geschätzt).", ["ui.realLoopMeasured"]="Echter Umlauf ca. {real} Min ({corr}x der {est}-Min-Schätzung, gemessen).", ["enum.VehicleCounts.HandsOff"]="Den Mod nicht entscheiden lassen", ["enum.VehicleCounts.ModDecides"]="Den Mod entscheiden lassen", ["ui.noticeAsk"]="Realistische Zeiten wieder einschalten? Die angezeigten Zeiten passen dann zur Strecke, und die Fahrzeuganzahl einer Linie kann entsprechend steigen.", ["opt.VehicleCounts.L"]="Fahrzeuganzahl", ["opt.VehicleCounts.D"]="Wer entscheidet, wie viele Fahrzeuge auf jeder Linie mit Fahrplan fahren. \"Den Mod entscheiden lassen\" (empfohlen) bemisst jede Linie anhand der gemessenen echten Fahrdauer, damit sie den eingestellten Takt tatsächlich halten kann, und erfordert keine Aufmerksamkeit. In diesem Modus bestimmt der Mod die Anzahl auf jeder Linie mit Fahrplan: Der spieleigene Regler für zugewiesene Fahrzeuge bleibt nicht erhalten, da der Mod seinen eigenen Wert erneut anwendet. \"Den Mod nicht entscheiden lassen\" gibt jede Linie zurück und rührt die Anzahl nie wieder an, sodass du oder ein spezialisierter Fuhrpark-Mod sie übernehmen kann. Das Halten bis zur Abfahrtszeit funktioniert in beiden Fällen gleich. Wenn eine Linie mehr Fahrzeuge verlangt, als du möchtest, vergrößere ihren Takt; das ist die eigentliche Stellschraube.", ["ui.noticeTitle"]="Realistische Zeiten sind ausgeschaltet", ["ui.noticeBody"]="Bisher hat dieser Mod immer gemessen, wie lange die Strecke jeder Linie wirklich dauert, und diesen Wert sowohl für die angezeigten Zeiten als auch für die Fahrzeuganzahl verwendet. Beides sind jetzt getrennte Einstellungen, und beide sind zunächst ausgeschaltet, daher verwendet diese Stadt die Schätzung des Spiels.", ["ui.noticeWhere"]="Du kannst das jederzeit in den Optionen unter Realismus ändern.", ["ui.noticeKeep"]="Einschalten", ["ui.noticeOff"]="Ausgeschaltet lassen", ["opt.StopAtEveryStop.L"]="An jeder Haltestelle halten (auch an leeren)", ["opt.StopAtEveryStop.D"]="Standardmäßig lässt Cities: Skylines II einen Bus eine Haltestelle ÜBERSPRINGEN, an der niemand wartet und niemand aussteigen will — er bremst nur ab und rollt durch, sodass diese Haltestelle nie bis zur planmäßigen Abfahrt gehalten wird und der Bus seinem Fahrplan vorauslaufen kann. Die Endhaltestelle wird nun unabhängig von dieser Einstellung immer zum Halten gezwungen (sie zu überspringen würde den ganzen Fahrplan sprengen). Aktiviere dies, um Busse zu zwingen, an JEDER Haltestelle einer getakteten Linie zu halten, sodass jede angezeigte Zeit eingehalten wird — auf Kosten einer kurzen Standzeit an jeder leeren Haltestelle, die Linien etwas langsamer macht. Betrifft nur Busse und andere Straßenfahrzeuge; Züge, Straßenbahnen, Schiffe und Flugzeuge halten bereits an jeder Station. Standardmäßig AUS.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / Zeitlupen-Kompatibilität — AN, wenn du RT oder Time2Work nutzt (ALPHA)", ["opt.RealisticTripsCompat.D"]="Standardmäßig AUS — lass es aus, außer du nutzt einen Mod, der den Spieltag verlängert (Time2Work / \"Realistic Trips\" oder ähnlich). Aktiviere es mit einem solchen Mod, und Abfahrten, Haltezeiten und Flottengrößen bleiben korrekt, statt zu früh zu laufen; der Mod misst die echte Taglänge automatisch. Ohne Zeitlupen-Mod bewirkt diese Einstellung nichts, und erkennt der Mod einen solchen, während dies AUS ist, vermerkt er es im Log. HINWEIS: Dieser Kompatibilitätspfad ist ALPHA und wurde noch NICHT im Spiel mit Realistic Trips getestet — bitte melde alles Auffällige. Unter Realistic Trips nutzen deine Linien korrekterweise weniger Fahrzeuge als zuvor.", ["opt.MorningPeakStart.L"]="Beginn der Morgenspitze", ["opt.MorningPeakStart.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit beginnt.", ["opt.MorningPeakEnd.L"]="Ende der Morgenspitze", ["opt.MorningPeakEnd.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit endet.", ["opt.EveningPeakStart.L"]="Beginn der Abendspitze", ["opt.EveningPeakStart.D"]="Stunde, zu der die abendliche Hauptverkehrszeit beginnt.", ["opt.EveningPeakEnd.L"]="Ende der Abendspitze", ["opt.EveningPeakEnd.D"]="Stunde, zu der die abendliche Hauptverkehrszeit endet.", ["opt.NightStart.L"]="Nachtbeginn", ["opt.NightStart.D"]="Stunde, zu der der Nachtbetrieb beginnt (kann über Mitternacht hinausgehen).", ["opt.NightEnd.L"]="Nachtende", ["opt.NightEnd.D"]="Stunde, zu der der Nachtbetrieb endet.", ["opt.Enabled.L"]="TransitTimetables aktivieren", ["opt.Enabled.D"]="Hauptschalter für den gesamten Mod. Aus = exakt Vanilla: jede Linie wird nicht mehr verwaltet (gehaltene Busse werden freigegeben und die vom Mod gesetzte Fahrzeuganzahl sowie der Entklumpungsfaktor werden zurückgesetzt), während deine linienbezogenen Fahrpläne erhalten bleiben, sodass ein erneutes Aktivieren sie fortsetzt. Standardmäßig AN.", ["grp.GroupWindows"]="Hauptverkehrszeiten", ["grp.GroupCompat"]="Kompatibilität", ["grp.GroupStops"]="Haltestellen", ["grp.GroupGeneral"]="Allgemein", ["ui.to"]="bis", ["ui.timetable"]="FAHRPLAN", ["ui.on"]="AN", ["ui.off"]="AUS", ["ui.ttNow"]="jetzt alle {i} Min · {f} Fahrzeuge", ["ui.ttNext"]="nächste: {n}", ["ui.firstDeparture"]="Erste Abfahrt", ["ui.peakInterval"]="Spitze", ["ui.offPeakInterval"]="Nebenzeit", ["ui.otherHours"]="übrige Stunden", ["ui.nightInterval"]="Nacht", ["ui.customLinePeak"]="Eigene Spitze (diese Linie)", ["ui.morningPeak"]="Morgenspitze", ["ui.eveningPeak"]="Abendspitze", ["ui.customPeakInterval"]="Eigenes Spitzenintervall", ["ui.terminusHint"]="Wähle eine Haltestelle, um ihre Abfahrten zu sehen und sie als Endhaltestelle dieser Linie festzulegen.", ["ui.noLines"]="Keine Linien bedienen diese Haltestelle.", ["ui.line"]="Linie {n}", ["ui.terminusBadge"]="Endhaltestelle", ["ui.departs"]="Abfahrt: {d}", ["ui.noDepartures"]="keine Abfahrten geplant", ["ui.notTimetabled"]="kein Fahrplan", ["ui.estimatedTimes"]="geschätzt, noch nicht gemessen", ["ui.setTerminusThis"]="Als Endhaltestelle festlegen", ["ui.setTerminusAll"]="Als Endhaltestelle für alle Linien hier festlegen", ["ui.setTerminusHint"]="Die Endhaltestelle verankert den Fahrplan und den Fahrzeughalt; Busse werden hier ausgemustert.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="ABFAHRTEN", ["ui.panelHint"]="Wähle eine Haltestelle, um die Abfahrten jeder Linie von dort zu sehen. Um den Fahrplan einer Linie zu bearbeiten, wähle die Linie — ihre Steuerung befindet sich im Infofenster der Linie.", },
                ["es-ES"] = new Dictionary<string, string> { ["ui.terminusNone"]="Esta línea no tiene ninguna terminal fijada, así que el horario se ancla a la primera parada del recorrido. Selecciona una parada a la que dé servicio esta línea y fíjala como terminal para elegir dónde esperan los vehículos su salida.", ["ui.terminusLost"]="La terminal de esta línea ya no está en su recorrido, así que el horario ha vuelto a la primera parada. Selecciona una parada a la que dé servicio esta línea y fíjala como terminal.", ["opt.ManageVehicleCount.L"]="Gestionar el número de vehículos", ["opt.ManageVehicleCount.D"]="Cuando está activado (predeterminado), el mod ajusta el número de vehículos de cada línea con horario para mantener el intervalo que elijas. Desactívalo para dejar el número de vehículos en tus manos o en las de otro mod de flota (como All Transit + Truck): el mod sigue reteniendo las salidas en la terminal, solo que no añade ni cambia autobuses. Una línea con muy pocos vehículos circulará entonces con un intervalo más amplio que el establecido.", ["opt.CleanUninstall.L"]="Eliminar todos los datos del mod de esta partida", ["opt.CleanUninstall.W"]="Esto BORRARÁ el horario de todas las líneas de esta ciudad y las devolverá al comportamiento del juego base. Tus horas de salida por línea, tus franjas de hora punta personalizadas y los datos de recorrido medidos se perderán y no se podrán recuperar.\n\nIMPORTANTE: tras confirmar, cierra este menú y deja que el juego AVANCE un momento; después, guarda. La limpieza se realiza en el siguiente paso de simulación, así que, si guardas con el juego en pausa, tu ciudad se guardaría sin cambios.\n\n¿Continuar?", ["opt.CleanUninstall.D"]="Limpieza única para una desinstalación limpia. Revierte todas las líneas a vanilla (libera los autobuses retenidos, restaura el factor de dispersión y elimina el número de vehículos fijado por el mod) y borra los datos que el mod ha guardado en esta ciudad (tus horarios por línea, tus horas punta personalizadas y los recorridos medidos). Púlsalo, deja luego que el juego avance un momento (la limpieza se realiza en el siguiente paso de simulación, así que en pausa no hace nada) y después GUARDA: a partir de ahí el mod se puede eliminar sin dejar ningún residuo. Borra tus horarios, así que primero pide confirmación. Es inofensivo si lo pulsas con el mod aún instalado: las líneas simplemente vuelven al comportamiento vanilla.", ["opt.MaxDwellRoad.L"]="Tiempo máximo de parada — autobuses (minutos tras la hora de salida)", ["opt.MaxDwellRoad.D"]="Cuánto tiempo puede seguir esperando un autobús, más allá de su hora de salida publicada, a los pasajeros que YA están subiendo. Es un límite, no un objetivo: un autobús en el que no sube nadie sale exactamente en su minuto publicado, y este ajuste nunca lo retrasa ni un segundo. Existe porque el juego base cuenta a alguien como pasajero en cuanto empieza a caminar hacia el vehículo, así que salir a rajatabla devolvería a la cola a todos los que aún están cruzando el andén. Ahora el vehículo los espera, pero nunca más de este tiempo. Por defecto, 3 minutos. Ponlo a 0 para salir en punto y no esperar a nadie. Nota: esto funciona acortando la propia ventana de embarque del juego base, así que nunca puede hacer que un vehículo espere MÁS TIEMPO del que esperaría el juego; y si usas un mod que alarga el día del juego, puede que los valores más altos de aquí no sean alcanzables.", ["opt.MaxDwellRail.L"]="Tiempo máximo de parada — trenes, metros y tranvías (minutos tras la hora de salida)", ["opt.MaxDwellRail.D"]="El mismo límite para el ferrocarril, también 3 minutos por defecto. Súbelo si ves que se acumula gente en un andén concurrido: un tren o un metro que intercambia un andén lleno de pasajeros tarda mucho más en cargarlos que un autobús, sus pasajeros se reparten a lo largo del andén para llegar a su propio vagón y, a diferencia de un autobús, nunca puede omitir una parada. Ten en cuenta que ese margen se aplica en todas las paradas, así que un valor generoso en una línea larga se va acumulando a lo largo de la vuelta; y unas paradas más largas significan una vuelta real más larga, así que la línea querrá más vehículos para mantener el mismo intervalo. Igual que con el valor de los autobuses, esto acorta la propia ventana de embarque del juego base en lugar de alargarla, así que con un mod de tiempo lento puede que los valores más altos no sean alcanzables.", ["opt.RealisticTravelTime.L"]="Tiempo de viaje realista (corrige los horarios publicados)", ["opt.RealisticTravelTime.D"]="La propia estimación del juego sobre lo que tarda una línea se queda corta respecto al recorrido real simulado: los autobuses aceleran y frenan en cada parada, algo que la estimación ignora (medido en vivo, alrededor de 1,7x en líneas con pocas paradas y hasta ~2,5x en las de muchas paradas). Actívalo y el mod mide el recorrido real de cada línea y publica horarios de parada realistas, de modo que el panel coincida con lo que los autobuses hacen de verdad. No cuesta nada: solo hace que el reloj sea honesto. Desactivado por defecto; los horarios existentes no se modifican hasta que lo actives.", ["opt.ProvisionRealFleet.L"]="Dimensionar la flota según el tiempo de viaje real (aumenta el número de vehículos)", ["opt.ProvisionRealFleet.D"]="Dimensiona también el número de vehículos de cada línea a su recorrido REAL en lugar de a la estimación. Esta es la opción que gasta: mantener un intervalo ajustado en una línea cuyo recorrido real es ~2x la estimación requiere aproximadamente el doble de vehículos, y el doble de mantenimiento. Desactivado (por defecto) mantiene el recuento basado en la estimación, con lo que una línea funciona en silencio con un intervalo efectivo mayor del que fijaste; activado la dimensiona para el recorrido real. Solo crece —nunca reduce una línea por debajo de la estimación— y tiene un tope, de modo que una lectura errónea no puede inundarte de autobuses.", ["ui.vehNotOnTimetable"]="Aún no está en el horario. Adopta su horario cuando llega por primera vez a la terminal.", ["ui.vehHolding"]="Espera aquí hasta las {at}, su salida programada.", ["ui.vehAtStopLate"]="En esta parada, {n} min por detrás de su salida de las {at}.", ["ui.vehAtStop"]="En esta parada, sale a las {at}.", ["ui.vehNextStop"]="Próxima parada prevista a las {at}.", ["ui.vehBehind"]="{n} min por detrás del horario. Su próxima parada estaba prevista a las {at}.", ["ui.vehRefining"]="Esta línea aún está midiendo su recorrido real, así que estos tiempos cambiarán.", ["ui.rttOffWarning"]="El tiempo de viaje realista está DESACTIVADO, así que los horarios usan la estimación del juego en lugar de este recorrido medido. Actívalo en las Opciones del mod para usar los tiempos medidos.", ["ui.loopMeasuring"]="El recorrido real aún se está midiendo ({laps} de {need} vueltas).", ["ui.loopRefining"]="Recorrido real de unos {real} min, aún ajustándose ({wlaps} de {need2} vueltas).", ["ui.loopMeasured"]="Recorrido real de {real} min, medido ({corr}x la estimación de {est} min).", ["ui.countMayRise"]="Esa cantidad es deliberadamente prudente y puede aumentar cuando termine la medición.", ["ui.sizingSoon"]="Esta línea se dimensionará en cuanto se estabilice su estimación de duración.", ["ui.notSetByMod"]="Este intervalo necesita ~{n} vehículos. Este mod no está fijando el número.", ["ui.provisioning"]="Se están aportando ~{n} vehículos para ello.", ["ui.realLoopEstimated"]="Vuelta real ~{real} min ({corr}x la estimación de {est} min, estimada).", ["ui.realLoopMeasured"]="Vuelta real ~{real} min ({corr}x la estimación de {est} min, medida).", ["enum.VehicleCounts.HandsOff"]="No dejar que decida el mod", ["enum.VehicleCounts.ModDecides"]="Dejar que decida el mod", ["ui.noticeAsk"]="¿Volver a activar los tiempos realistas? Los horarios coincidirán con el recorrido y el número de vehículos de una línea puede aumentar en consecuencia.", ["opt.VehicleCounts.L"]="Número de vehículos", ["opt.VehicleCounts.D"]="Quién decide cuántos vehículos circulan en cada línea con horario. \"Dejar que decida el mod\" (recomendado) dimensiona cada línea midiendo lo que tarda realmente su recorrido, para que pueda mantener el intervalo que has fijado, y no requiere atención. En este modo el mod controla el número en todas las líneas con horario: el control de vehículos asignados del juego no se mantendrá, porque el mod vuelve a aplicar su propio valor. \"No dejar que decida el mod\" devuelve todas las líneas y no vuelve a tocar el número, de modo que tú o un mod de flotas dedicado podáis gestionarlo. Las esperas de salida funcionan igual en ambos casos. Si una línea pide más vehículos de los que quieres, amplía su intervalo; ese es el control real.", ["ui.noticeTitle"]="Los tiempos realistas están desactivados", ["ui.noticeBody"]="Hasta ahora, este mod siempre medía cuánto tarda realmente el recorrido de cada línea y usaba ese valor tanto para los horarios mostrados como para el número de vehículos. Ahora son dos ajustes distintos y ambos empiezan desactivados, así que esta ciudad usa la estimación del propio juego.", ["ui.noticeWhere"]="Puedes cambiarlo en cualquier momento en Opciones, en Realismo.", ["ui.noticeKeep"]="Activarlos", ["ui.noticeOff"]="Dejarlos desactivados", ["opt.StopAtEveryStop.L"]="Parar en todas las paradas (incluso las vacías)", ["opt.StopAtEveryStop.D"]="Por defecto, Cities: Skylines II permite que un autobús OMITA una parada donde nadie espera y nadie quiere bajar: solo reduce la velocidad y pasa de largo, así que esa parada nunca se retiene hasta su salida programada y el autobús puede adelantarse a su horario. La terminal ahora siempre se fuerza a parar, independientemente de esta opción (omitirla dejaría colgado todo el horario). Activa esto para forzar a los autobuses a detenerse en TODAS las paradas de una línea con horario, de modo que se respeten todas las horas publicadas, a costa de una breve espera en cada parada vacía, lo que hace que las líneas vayan un poco más lentas. Afecta solo a autobuses y otros vehículos de carretera; trenes, tranvías, barcos y aviones ya paran en todas las estaciones. Desactivado por defecto.", ["opt.RealisticTripsCompat.L"]="Compatibilidad con Realistic Trips / tiempo lento — actívalo si usas RT o Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desactivado por defecto: déjalo así salvo que uses un mod que alargue el día del juego (Time2Work / \"Realistic Trips\" o similar). Actívalo con un mod de ese tipo y las salidas, los horarios de parada y el tamaño de la flota seguirán siendo correctos en lugar de adelantarse; el mod mide automáticamente la duración real del día. Sin un mod de tiempo lento, esta opción no hace nada, y si el mod detecta uno mientras esto está desactivado lo anotará en el registro. NOTA: esta vía de compatibilidad es ALFA y AÚN NO se ha probado con Realistic Trips en el juego; informa de cualquier anomalía. Con Realistic Trips, tus líneas usarán correctamente menos vehículos que antes.", ["opt.MorningPeakStart.L"]="Inicio de la hora punta de la mañana", ["opt.MorningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la mañana.", ["opt.MorningPeakEnd.L"]="Fin de la hora punta de la mañana", ["opt.MorningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la mañana.", ["opt.EveningPeakStart.L"]="Inicio de la hora punta de la tarde", ["opt.EveningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la tarde.", ["opt.EveningPeakEnd.L"]="Fin de la hora punta de la tarde", ["opt.EveningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la tarde.", ["opt.NightStart.L"]="Inicio de la noche", ["opt.NightStart.D"]="Hora en que empieza el servicio nocturno (puede pasar de la medianoche).", ["opt.NightEnd.L"]="Fin de la noche", ["opt.NightEnd.D"]="Hora en que termina el servicio nocturno.", ["opt.Enabled.L"]="Activar TransitTimetables", ["opt.Enabled.D"]="Interruptor principal de todo el mod. Desactivado = vanilla exacto: todas las líneas dejan de gestionarse (los autobuses retenidos se liberan y se revierten el recuento de flota y el factor de dispersión aplicados por el mod), mientras que tus horarios por línea se conservan para que reactivarlo los reanude. Activado por defecto.", ["grp.GroupWindows"]="Franjas de hora punta", ["grp.GroupCompat"]="Compatibilidad", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="General", ["ui.to"]="a", ["ui.timetable"]="HORARIO", ["ui.on"]="SÍ", ["ui.off"]="NO", ["ui.ttNow"]="ahora cada {i} min · {f} vehículos", ["ui.ttNext"]="siguiente: {n}", ["ui.firstDeparture"]="Primera salida", ["ui.peakInterval"]="Hora punta", ["ui.offPeakInterval"]="Fuera de punta", ["ui.otherHours"]="otras horas", ["ui.nightInterval"]="Noche", ["ui.customLinePeak"]="Hora punta personalizada (esta línea)", ["ui.morningPeak"]="Hora punta de la mañana", ["ui.eveningPeak"]="Hora punta de la tarde", ["ui.customPeakInterval"]="Intervalo de hora punta personalizado", ["ui.terminusHint"]="Selecciona una parada para ver sus salidas y fijarla como terminal de esta línea.", ["ui.noLines"]="Ninguna línea da servicio a esta parada.", ["ui.line"]="Línea {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="sale: {d}", ["ui.noDepartures"]="sin salidas programadas", ["ui.notTimetabled"]="sin horario", ["ui.estimatedTimes"]="estimado, aún sin medir", ["ui.setTerminusThis"]="Fijar como terminal", ["ui.setTerminusAll"]="Fijar como terminal para todas las líneas de aquí", ["ui.setTerminusHint"]="La terminal ancla el horario y la retención de vehículos; los autobuses se retiran aquí.", ["ui.buttonTooltip"]="Horarios de transporte", ["ui.panelTitle"]="SALIDAS", ["ui.panelHint"]="Selecciona una parada para ver las salidas de todas las líneas desde ella. Para editar el horario de una línea, selecciona la línea: sus controles están en el panel de información de la línea.", },
                ["fr-FR"] = new Dictionary<string, string> { ["ui.terminusNone"]="Aucun terminus n'est défini pour cette ligne, l'horaire est donc ancré au premier arrêt du parcours. Sélectionnez un arrêt desservi par cette ligne et définissez-le comme terminus pour choisir où les véhicules attendent leur départ.", ["ui.terminusLost"]="Le terminus de cette ligne n'est plus sur son parcours, l'horaire est donc revenu au premier arrêt. Sélectionnez un arrêt desservi par cette ligne et définissez-le comme terminus.", ["opt.ManageVehicleCount.L"]="Gérer le nombre de véhicules", ["opt.ManageVehicleCount.D"]="Lorsque cette option est activée (par défaut), le mod règle le nombre de véhicules de chaque ligne dotée d'horaires afin de respecter l'intervalle que vous avez choisi. Désactivez-la pour laisser le nombre de véhicules à votre gré ou à celui d'un autre mod de flotte (comme All Transit + Truck) : le mod continue de retenir les départs au terminus, il n'ajoute ni ne modifie simplement pas les bus. Une ligne comptant trop peu de véhicules circulera alors simplement à un intervalle plus large que celui défini.", ["opt.CleanUninstall.L"]="Supprimer de cette sauvegarde toutes les données du mod", ["opt.CleanUninstall.W"]="Cela SUPPRIMERA l'horaire de chaque ligne de cette ville et rendra à toutes les lignes le comportement du jeu de base. Vos heures de départ par ligne, vos plages de pointe personnalisées et vos données de trajet mesurées seront perdues et ne pourront pas être récupérées.\n\nIMPORTANT : après confirmation, fermez ce menu et laissez le jeu TOURNER un instant, puis sauvegardez. Le nettoyage a lieu au prochain pas de simulation, donc sauvegarder en pause enregistrerait votre ville sans aucun changement.\n\nContinuer ?", ["opt.CleanUninstall.D"]="Nettoyage unique pour une désinstallation propre. Ramène chaque ligne au comportement du jeu de base (libère les bus retenus, rétablit le désengorgement, abandonne le nombre de véhicules défini par le mod) et supprime les données enregistrées du mod dans cette ville (vos horaires par ligne, vos pointes personnalisées et les trajets mesurés). Appuyez ici, puis laissez le jeu tourner un instant (le nettoyage a lieu au prochain pas de simulation, il ne fait donc rien en pause), puis SAUVEGARDEZ — après quoi le mod peut être retiré sans le moindre résidu. Cela efface vos horaires, une confirmation vous est donc demandée au préalable. Sans danger si vous appuyez dessus alors que le mod est toujours installé — les lignes reviennent simplement au comportement d'origine du jeu de base.", ["opt.MaxDwellRoad.L"]="Temps d'arrêt maximal — bus (minutes après l'heure de départ)", ["opt.MaxDwellRoad.D"]="Combien de temps un bus peut continuer d'attendre, au-delà de son départ prévu, les passagers qui sont DÉJÀ en train de monter à bord. C'est une limite, pas un objectif : un bus dans lequel personne ne monte part toujours exactement à la minute prévue, et ce réglage ne le retarde jamais d'une seconde. Il existe parce que le jeu de base considère une personne comme passager dès l'instant où elle se met à marcher vers le véhicule : partir sans attendre renverrait dans la file tous ceux qui sont encore en train de traverser le quai. Le véhicule les attend donc, mais jamais au-delà de cette limite. 3 minutes par défaut. Réglez-le sur 0 pour partir à l'heure pile et n'attendre personne. Note : cela fonctionne en raccourcissant la fenêtre d'embarquement du jeu de base, donc cela ne peut jamais faire attendre un véhicule PLUS LONGTEMPS que le jeu ne le ferait — et si vous utilisez un mod qui allonge la journée en jeu, les valeurs les plus élevées risquent de ne pas être atteignables.", ["opt.MaxDwellRail.L"]="Temps d'arrêt maximal — trains, métros et tramways (minutes après l'heure de départ)", ["opt.MaxDwellRail.D"]="La même limite pour le rail, également 3 minutes par défaut. Augmentez-la si vous voyez les gens s'entasser sur un quai très fréquenté : un train ou un métro qui doit faire monter et descendre tout un quai met bien plus de temps à se remplir qu'un bus, ses passagers se répartissent le long du quai pour rejoindre leur propre voiture, et, contrairement à un bus, il ne peut jamais sauter un arrêt. Gardez à l'esprit que cette marge s'applique à chaque arrêt : une valeur généreuse sur une longue ligne s'additionne tout au long de la boucle — et des arrêts plus longs signifient une boucle réelle plus longue, la ligne demandera donc plus de véhicules pour tenir le même intervalle. Comme pour le réglage des bus, cela raccourcit la fenêtre d'embarquement du jeu de base au lieu de l'allonger, donc avec un mod de temps ralenti les valeurs les plus élevées risquent de ne pas être atteignables.", ["opt.RealisticTravelTime.L"]="Temps de trajet réaliste (corrige les horaires affichés)", ["opt.RealisticTravelTime.D"]="L'estimation du jeu de la durée d'une ligne sous-évalue la boucle réelle simulée — les bus accélèrent et freinent à chaque arrêt, ce que l'estimation ignore (mesuré en direct à environ 1,7x sur les lignes espacées, jusqu'à ~2,5x sur celles à arrêts rapprochés). Activez cette option et le mod mesure la boucle réelle de chaque ligne et affiche des horaires d'arrêt réalistes, pour que le tableau corresponde à ce que font vraiment les bus. Ne coûte rien — cela rend simplement l'horloge honnête. Désactivé par défaut ; les horaires existants restent inchangés jusqu'à ce que vous l'activiez.", ["opt.ProvisionRealFleet.L"]="Dimensionner la flotte selon le temps de trajet réel (augmente le nombre de véhicules)", ["opt.ProvisionRealFleet.D"]="Dimensionne aussi le nombre de véhicules de chaque ligne d'après sa boucle RÉELLE plutôt que d'après l'estimation. C'est l'option qui dépense : maintenir un intervalle serré sur une ligne dont la boucle réelle fait ~2x l'estimation demande environ deux fois plus de véhicules, et deux fois plus d'entretien. Désactivé (par défaut) conserve le nombre basé sur l'estimation, donc une ligne applique en silence un intervalle effectif plus long que celui que vous avez réglé ; activé dimensionne pour la boucle réelle. Croissance uniquement — ne réduit jamais une ligne en dessous de l'estimation — et plafonné, pour qu'une mauvaise mesure ne vous inonde pas de bus.", ["ui.vehNotOnTimetable"]="Pas encore sur l'horaire. Il prend son horaire dès qu'il atteint le terminus pour la première fois.", ["ui.vehHolding"]="Attend ici jusqu'à {at}, son départ prévu.", ["ui.vehAtStopLate"]="À cet arrêt, {n} min de retard sur son départ de {at}.", ["ui.vehAtStop"]="À cet arrêt, départ à {at}.", ["ui.vehNextStop"]="Prochain arrêt prévu à {at}.", ["ui.vehBehind"]="{n} min de retard. Son prochain arrêt était prévu à {at}.", ["ui.vehRefining"]="Cette ligne mesure encore sa boucle réelle, ces horaires vont donc évoluer.", ["ui.rttOffWarning"]="Le temps de trajet réaliste est DÉSACTIVÉ : les horaires affichés utilisent l'estimation du jeu plutôt que cette boucle mesurée. Activez-le dans les Options du mod pour utiliser les temps mesurés.", ["ui.loopMeasuring"]="La boucle réelle est encore en cours de mesure ({laps} sur {need} tours).", ["ui.loopRefining"]="Boucle réelle d'environ {real} min, en cours d'affinage ({wlaps} sur {need2} tours).", ["ui.loopMeasured"]="Boucle réelle de {real} min, mesurée ({corr}x l'estimation de {est} min).", ["ui.countMayRise"]="Ce nombre est volontairement prudent et pourra augmenter une fois la mesure terminée.", ["ui.sizingSoon"]="Cette ligne sera dimensionnée dès que son estimation de durée sera stable.", ["ui.notSetByMod"]="Cet intervalle nécessite ~{n} véhicules. Ce mod ne définit pas le nombre.", ["ui.provisioning"]="~{n} véhicules sont fournis pour cela.", ["ui.realLoopEstimated"]="Boucle réelle ~{real} min ({corr}x l'estimation de {est} min, estimée).", ["ui.realLoopMeasured"]="Boucle réelle ~{real} min ({corr}x l'estimation de {est} min, mesurée).", ["enum.VehicleCounts.HandsOff"]="Ne pas laisser le mod décider", ["enum.VehicleCounts.ModDecides"]="Laisser le mod décider", ["ui.noticeAsk"]="Réactiver les horaires réalistes ? Les horaires affichés correspondront alors au trajet, et le nombre de véhicules d'une ligne pourra augmenter en conséquence.", ["opt.VehicleCounts.L"]="Nombre de véhicules", ["opt.VehicleCounts.D"]="Qui décide du nombre de véhicules de chaque ligne avec horaires. \"Laisser le mod décider\" (recommandé) dimensionne chaque ligne en mesurant la durée réelle de son parcours, afin qu'elle puisse tenir l'intervalle que vous avez fixé, et ne demande aucune attention. Dans ce mode, le mod contrôle le nombre sur toutes les lignes avec horaires : le curseur de véhicules affectés du jeu ne sera pas conservé, car le mod réapplique sa propre valeur. \"Ne pas laisser le mod décider\" rend toutes les lignes et ne touche plus jamais au nombre, pour que vous ou un mod de flotte dédié puissiez le gérer. L'attente au départ fonctionne de la même façon dans les deux cas. Si une ligne demande plus de véhicules que vous ne le souhaitez, élargissez son intervalle ; c'est le véritable réglage.", ["ui.noticeTitle"]="Les horaires réalistes sont désactivés", ["ui.noticeBody"]="Jusqu'ici, ce mod mesurait toujours la durée réelle du trajet de chaque ligne et utilisait cette mesure à la fois pour les horaires affichés et pour le nombre de véhicules. Ce sont désormais deux réglages distincts, tous deux désactivés au départ : cette ville utilise donc l'estimation du jeu.", ["ui.noticeWhere"]="Vous pouvez le changer à tout moment dans les Options, sous Réalisme.", ["ui.noticeKeep"]="Les activer", ["ui.noticeOff"]="Les laisser désactivés", ["opt.StopAtEveryStop.L"]="S'arrêter à chaque arrêt (même vides)", ["opt.StopAtEveryStop.D"]="Par défaut, Cities: Skylines II autorise un bus à SAUTER un arrêt où personne n'attend et personne ne veut descendre — il ne fait que ralentir et passer, si bien que cet arrêt n'est jamais retenu jusqu'à son départ prévu et que le bus peut prendre de l'avance sur son horaire. Le terminus est désormais toujours forcé à s'arrêter quel que soit ce réglage (le sauter désorganiserait tout l'horaire). Activez cette option pour forcer les bus à s'arrêter à CHAQUE arrêt d'une ligne à horaire, afin que chaque horaire affiché soit respecté — au prix d'un court arrêt à chaque arrêt vide, ce qui ralentit un peu les lignes. Concerne uniquement les bus et autres véhicules routiers ; les trains, tramways, navires et avions s'arrêtent déjà à chaque station. Désactivé par défaut.", ["opt.RealisticTripsCompat.L"]="Compatibilité Realistic Trips / temps ralenti — activez si vous utilisez RT ou Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Désactivé par défaut — laissez-le désactivé sauf si vous utilisez un mod qui allonge la journée en jeu (Time2Work / \\\"Realistic Trips\\\" ou similaire). Activez-le avec un tel mod et les départs, horaires d'arrêt et tailles de flotte restent corrects au lieu d'être en avance ; le mod mesure automatiquement la durée réelle de la journée. Sans mod de temps ralenti ce réglage ne fait rien, et si le mod en détecte un alors que ceci est désactivé il le signalera dans le journal. NOTE : ce chemin de compatibilité est en ALPHA et n'a PAS encore été testé en jeu avec Realistic Trips — merci de signaler tout comportement étrange. Sous Realistic Trips vos lignes utiliseront correctement moins de véhicules qu'auparavant.", ["opt.MorningPeakStart.L"]="Début de la pointe du matin", ["opt.MorningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du matin.", ["opt.MorningPeakEnd.L"]="Fin de la pointe du matin", ["opt.MorningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du matin.", ["opt.EveningPeakStart.L"]="Début de la pointe du soir", ["opt.EveningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du soir.", ["opt.EveningPeakEnd.L"]="Fin de la pointe du soir", ["opt.EveningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du soir.", ["opt.NightStart.L"]="Début de nuit", ["opt.NightStart.D"]="Heure à laquelle commence le service de nuit (peut passer minuit).", ["opt.NightEnd.L"]="Fin de nuit", ["opt.NightEnd.D"]="Heure à laquelle se termine le service de nuit.", ["opt.Enabled.L"]="Activer TransitTimetables", ["opt.Enabled.D"]="Interrupteur principal de tout le mod. Désactivé = jeu de base exact : toutes les lignes cessent d'être gérées (les bus retenus sont libérés et le nombre de véhicules ainsi que le facteur de désengorgement appliqués par le mod sont rétablis), tandis que vos horaires par ligne sont conservés pour reprendre à la réactivation. Activé par défaut.", ["grp.GroupWindows"]="Plages de pointe", ["grp.GroupCompat"]="Compatibilité", ["grp.GroupStops"]="Arrêts", ["grp.GroupGeneral"]="Général", ["ui.to"]="à", ["ui.timetable"]="HORAIRE", ["ui.on"]="ACTIVÉ", ["ui.off"]="DÉSACTIVÉ", ["ui.ttNow"]="actuellement toutes les {i} min · {f} véhicules", ["ui.ttNext"]="suivant : {n}", ["ui.firstDeparture"]="Premier départ", ["ui.peakInterval"]="Pointe", ["ui.offPeakInterval"]="Heures creuses", ["ui.otherHours"]="autres heures", ["ui.nightInterval"]="Nuit", ["ui.customLinePeak"]="Pointe personnalisée (cette ligne)", ["ui.morningPeak"]="Pointe du matin", ["ui.eveningPeak"]="Pointe du soir", ["ui.customPeakInterval"]="Intervalle de pointe personnalisé", ["ui.terminusHint"]="Sélectionnez un arrêt pour voir ses départs et le définir comme terminus de cette ligne.", ["ui.noLines"]="Aucune ligne ne dessert cet arrêt.", ["ui.line"]="Ligne {n}", ["ui.terminusBadge"]="terminus", ["ui.departs"]="départ : {d}", ["ui.noDepartures"]="aucun départ prévu", ["ui.notTimetabled"]="sans horaire", ["ui.estimatedTimes"]="estimé, pas encore mesuré", ["ui.setTerminusThis"]="Définir comme terminus", ["ui.setTerminusAll"]="Définir comme terminus pour toutes les lignes ici", ["ui.setTerminusHint"]="Le terminus ancre l'horaire et la rétention des véhicules ; les bus sont retirés ici.", ["ui.buttonTooltip"]="Horaires de transport", ["ui.panelTitle"]="DÉPARTS", ["ui.panelHint"]="Sélectionnez un arrêt pour voir les départs de chaque ligne depuis cet arrêt. Pour modifier l'horaire d'une ligne, sélectionnez la ligne — ses réglages se trouvent dans le panneau d'informations de la ligne.", },
                ["it-IT"] = new Dictionary<string, string> { ["ui.terminusNone"]="Nessun capolinea è impostato per questa linea, quindi l'orario è ancorato alla prima fermata del percorso. Seleziona una fermata servita da questa linea e impostala come capolinea per scegliere dove i veicoli attendono la loro partenza.", ["ui.terminusLost"]="Il capolinea di questa linea non è più sul suo percorso, quindi l'orario è tornato alla prima fermata. Seleziona una fermata servita da questa linea e impostala come capolinea.", ["opt.ManageVehicleCount.L"]="Gestisci il numero di veicoli", ["opt.ManageVehicleCount.D"]="Quando è attivo (predefinito), la mod imposta il numero di veicoli di ogni linea con orario per mantenere l'intervallo che hai scelto. Disattivalo per lasciare il numero di veicoli a te o a un'altra mod per la flotta (come All Transit + Truck): la mod continua a trattenere le partenze al capolinea, semplicemente non aggiunge né modifica gli autobus. Una linea con troppo pochi veicoli viaggerà quindi con un intervallo più ampio di quello impostato.", ["opt.CleanUninstall.L"]="Rimuovi tutti i dati della mod da questo salvataggio", ["opt.CleanUninstall.W"]="Questa operazione ELIMINERÀ l'orario di ogni linea di questa città e riporterà tutte le linee al comportamento del gioco base. Gli orari di partenza delle singole linee, le fasce di picco personalizzate e i dati di percorrenza misurati andranno persi e non potranno essere recuperati.\n\nIMPORTANTE: dopo aver confermato, chiudi questo menu e lascia SCORRERE il gioco per qualche istante, poi salva. La pulizia avviene al passo di simulazione successivo, quindi salvare a gioco in pausa salverebbe la tua città senza alcuna modifica.\n\nContinuare?", ["opt.CleanUninstall.D"]="Pulizia una tantum per una disinstallazione pulita. Riporta ogni linea al comportamento originale (rilascia gli autobus trattenuti, ripristina la riduzione degli ammassamenti, rinuncia al numero di veicoli impostato dalla mod) e rimuove i dati salvati della mod da questa città (gli orari delle singole linee, i picchi personalizzati e i dati di percorrenza misurati). Premi questo pulsante, poi lascia scorrere il gioco per qualche istante (la pulizia avviene al passo di simulazione successivo, quindi a gioco in pausa non fa nulla), poi SALVA: dopodiché la mod può essere rimossa senza lasciare alcun residuo. Poiché cancella i tuoi orari, chiede prima una conferma. È innocuo premerlo con la mod ancora installata: le linee tornano semplicemente al comportamento originale.", ["opt.MaxDwellRoad.L"]="Tempo massimo di sosta — autobus (minuti oltre l'orario di partenza)", ["opt.MaxDwellRoad.D"]="Per quanto tempo un autobus può continuare ad aspettare, oltre l'orario di partenza esposto, i passeggeri che stanno GIÀ salendo. È un limite, non un obiettivo: un autobus su cui non sale nessuno parte comunque esattamente al minuto esposto, e questa impostazione non lo ritarda di un secondo. Esiste perché il gioco base considera qualcuno un passeggero nel momento stesso in cui inizia a camminare verso il veicolo, quindi partire rigidamente all'orario rimetterebbe in coda tutti quelli che stanno ancora attraversando la banchina. Ora invece il veicolo li aspetta, ma mai oltre questo limite. Valore predefinito 3 minuti. Impostalo a 0 per partire in punto senza aspettare nessuno. Nota: questo funziona accorciando la finestra di salita del gioco base, quindi non può mai far attendere un veicolo PIÙ A LUNGO di quanto farebbe il gioco — e se usi una mod che allunga la giornata di gioco, i valori più alti potrebbero non essere raggiungibili.", ["opt.MaxDwellRail.L"]="Tempo massimo di sosta — treni, metropolitane e tram (minuti oltre l'orario di partenza)", ["opt.MaxDwellRail.D"]="Lo stesso limite per i mezzi su rotaia, anch'esso 3 minuti per impostazione predefinita. Aumentalo se vedi le persone accalcarsi su una banchina affollata: un treno o una metropolitana che deve far scendere e salire un'intera banchina impiega molto più tempo di un autobus a caricare, i suoi passeggeri si distribuiscono lungo la banchina per raggiungere la propria carrozza e, a differenza di un autobus, non può mai saltare una fermata. Tieni presente che questo margine si applica a ogni fermata, quindi un valore generoso su una linea lunga si somma lungo tutto il giro — e soste più lunghe significano un giro reale più lungo, quindi la linea chiederà più veicoli per mantenere lo stesso intervallo. Come per il valore degli autobus, questo accorcia la finestra di salita del gioco base anziché allungarla, quindi con una mod che rallenta il tempo di gioco i valori più alti potrebbero non essere raggiungibili.", ["opt.RealisticTravelTime.L"]="Tempo di percorrenza realistico (corregge gli orari esposti)", ["opt.RealisticTravelTime.D"]="La stima del gioco sulla durata di una linea è inferiore al percorso reale simulato: gli autobus accelerano e frenano a ogni fermata, cosa che la stima ignora (misurato dal vivo a circa 1,7x sulle linee con poche fermate, fino a ~2,5x su quelle con molte fermate). Attiva questa opzione e la mod misura il giro reale di ogni linea ed espone orari di fermata realistici, così il tabellone corrisponde a ciò che gli autobus fanno davvero. Non costa nulla: rende soltanto onesto l'orologio. Disattivata per impostazione predefinita; gli orari esistenti restano invariati finché non la abiliti.", ["opt.ProvisionRealFleet.L"]="Dimensiona la flotta in base al tempo di percorrenza reale (aumenta il numero di veicoli)", ["opt.ProvisionRealFleet.D"]="Dimensiona anche il numero di veicoli di ogni linea sul suo giro REALE anziché sulla stima. È questa l'opzione che comporta spese: mantenere una frequenza stretta su una linea il cui giro reale è ~2x la stima richiede circa il doppio dei veicoli, e il doppio dei costi di gestione. Disattivata (predefinita) mantiene il conteggio basato sulla stima, così una linea usa silenziosamente una frequenza effettiva più lunga di quella impostata; attivata dimensiona la flotta sul giro reale. Solo in aumento — non riduce mai una linea al di sotto della stima — e con un limite massimo, così una lettura errata non può inondarti di autobus.", ["ui.vehNotOnTimetable"]="Non è ancora in orario di servizio. Riceve il suo orario quando raggiunge il capolinea per la prima volta.", ["ui.vehHolding"]="Attende qui fino alle {at}, la sua partenza prevista.", ["ui.vehAtStopLate"]="A questa fermata, {n} min in ritardo sulla partenza delle {at}.", ["ui.vehAtStop"]="A questa fermata, partenza alle {at}.", ["ui.vehNextStop"]="Prossima fermata prevista alle {at}.", ["ui.vehBehind"]="{n} min in ritardo. La prossima fermata era prevista alle {at}.", ["ui.vehRefining"]="Questa linea sta ancora misurando il suo giro reale, quindi questi orari cambieranno.", ["ui.rttOffWarning"]="Il tempo di percorrenza realistico è DISATTIVATO, quindi gli orari usano la stima del gioco invece di questo giro misurato. Attivalo nelle Opzioni della mod per usare i tempi misurati.", ["ui.loopMeasuring"]="Il giro reale è ancora in fase di misurazione ({laps} di {need} giri).", ["ui.loopRefining"]="Giro reale di circa {real} min, ancora in affinamento ({wlaps} di {need2} giri).", ["ui.loopMeasured"]="Giro reale di {real} min, misurato ({corr}x la stima di {est} min).", ["ui.countMayRise"]="Questo numero è volutamente prudente e potrebbe aumentare al termine della misurazione.", ["ui.sizingSoon"]="Questa linea verrà dimensionata appena la stima della durata sarà stabile.", ["ui.notSetByMod"]="Questo intervallo richiede ~{n} veicoli. Questa mod non imposta il numero.", ["ui.provisioning"]="Vengono forniti ~{n} veicoli a questo scopo.", ["ui.realLoopEstimated"]="Giro reale ~{real} min ({corr}x la stima di {est} min, stimato).", ["ui.realLoopMeasured"]="Giro reale ~{real} min ({corr}x la stima di {est} min, misurato).", ["enum.VehicleCounts.HandsOff"]="Non lasciare decidere alla mod", ["enum.VehicleCounts.ModDecides"]="Lascia decidere alla mod", ["ui.noticeAsk"]="Riattivare i tempi realistici? Gli orari corrisponderanno al percorso e il numero di veicoli di una linea potrà aumentare di conseguenza.", ["opt.VehicleCounts.L"]="Numero di veicoli", ["opt.VehicleCounts.D"]="Chi decide quanti veicoli circolano su ogni linea con orario. \"Lascia decidere alla mod\" (consigliato) dimensiona ogni linea misurando quanto dura davvero il suo percorso, così da poter rispettare l'intervallo impostato, e non richiede attenzione. In questa modalità la mod controlla il numero su tutte le linee con orario: il cursore dei veicoli assegnati del gioco non verrà mantenuto, perché la mod riapplica il proprio valore. \"Non lasciare decidere alla mod\" restituisce tutte le linee e non tocca mai più il numero, così tu o una mod dedicata alla flotta potete gestirlo. L'attesa alla partenza funziona allo stesso modo in entrambi i casi. Se una linea chiede più veicoli di quanti ne desideri, allarga il suo intervallo; quello è il controllo vero.", ["ui.noticeTitle"]="I tempi realistici sono disattivati", ["ui.noticeBody"]="Finora questa mod misurava sempre quanto dura davvero il percorso di ogni linea e usava quel valore sia per gli orari mostrati sia per il numero di veicoli. Ora sono due impostazioni distinte, entrambe disattivate all'inizio, quindi questa città usa la stima del gioco.", ["ui.noticeWhere"]="Puoi cambiarlo in qualsiasi momento nelle Opzioni, alla voce Realismo.", ["ui.noticeKeep"]="Attivali", ["ui.noticeOff"]="Lasciali disattivati", ["opt.StopAtEveryStop.L"]="Ferma a ogni fermata (anche quelle vuote)", ["opt.StopAtEveryStop.D"]="Per impostazione predefinita Cities: Skylines II consente a un autobus di SALTARE una fermata dove nessuno è in attesa e nessuno vuole scendere — rallenta soltanto e prosegue, così quella fermata non viene mai trattenuta fino alla partenza programmata e l'autobus può portarsi in anticipo sull'orario. Il capolinea è ora sempre obbligato a fermarsi indipendentemente da questa impostazione (saltarlo comprometterebbe l'intero orario). Attiva questa opzione per obbligare gli autobus a fermarsi a OGNI fermata di una linea con orario, così ogni orario esposto viene rispettato — al prezzo di una breve sosta a ogni fermata vuota, che rende le linee un po' più lente. Riguarda solo autobus e altri veicoli su strada; treni, tram, navi e aerei si fermano già a ogni stazione. Disattivata per impostazione predefinita.", ["opt.RealisticTripsCompat.L"]="Compatibilità con Realistic Trips / tempo rallentato — attiva se usi RT o Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Disattivata per impostazione predefinita — lasciala disattivata a meno che tu non usi una mod che allunga la giornata di gioco (Time2Work / \\\"Realistic Trips\\\" o simili). Attivala con una mod di questo tipo e le partenze, gli orari di fermata e le dimensioni della flotta restano corretti anziché anticipare; la mod misura automaticamente la durata reale della giornata. Senza una mod di tempo rallentato questa impostazione non fa nulla, e se la mod ne rileva una mentre è disattivata lo segnalerà nel log. NOTA: questo percorso di compatibilità è in fase ALPHA e NON è ancora stato testato in gioco con Realistic Trips — segnala qualunque anomalia. Con Realistic Trips le tue linee useranno correttamente meno veicoli rispetto a prima.", ["opt.MorningPeakStart.L"]="Inizio picco mattutino", ["opt.MorningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco mattutino.", ["opt.MorningPeakEnd.L"]="Fine picco mattutino", ["opt.MorningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco mattutino.", ["opt.EveningPeakStart.L"]="Inizio picco serale", ["opt.EveningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco serale.", ["opt.EveningPeakEnd.L"]="Fine picco serale", ["opt.EveningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco serale.", ["opt.NightStart.L"]="Inizio notte", ["opt.NightStart.D"]="Ora in cui inizia il servizio notturno (può proseguire oltre la mezzanotte).", ["opt.NightEnd.L"]="Fine notte", ["opt.NightEnd.D"]="Ora in cui termina il servizio notturno.", ["opt.Enabled.L"]="Abilita TransitTimetables", ["opt.Enabled.D"]="Interruttore principale dell'intera mod. Disattivato = comportamento originale esatto: ogni linea smette di essere gestita (gli autobus eventualmente trattenuti vengono rilasciati e il conteggio della flotta e il fattore di riduzione degli ammassamenti applicati dalla mod vengono ripristinati), mentre gli orari delle singole linee vengono conservati così che riabilitandola riprendano. Attivato per impostazione predefinita.", ["grp.GroupWindows"]="Fasce di picco", ["grp.GroupCompat"]="Compatibilità", ["grp.GroupStops"]="Fermate", ["grp.GroupGeneral"]="Generale", ["ui.to"]="alle", ["ui.timetable"]="ORARIO", ["ui.on"]="ATTIVO", ["ui.off"]="DISATTIVO", ["ui.ttNow"]="ora ogni {i} min · {f} veicoli", ["ui.ttNext"]="prossima: {n}", ["ui.firstDeparture"]="Prima partenza", ["ui.peakInterval"]="Picco", ["ui.offPeakInterval"]="Fuori picco", ["ui.otherHours"]="altre ore", ["ui.nightInterval"]="Notte", ["ui.customLinePeak"]="Picco personalizzato (questa linea)", ["ui.morningPeak"]="Picco mattutino", ["ui.eveningPeak"]="Picco serale", ["ui.customPeakInterval"]="Intervallo di picco personalizzato", ["ui.terminusHint"]="Seleziona una fermata per vedere le sue partenze e impostarla come capolinea di questa linea.", ["ui.noLines"]="Nessuna linea serve questa fermata.", ["ui.line"]="Linea {n}", ["ui.terminusBadge"]="capolinea", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nessuna partenza programmata", ["ui.notTimetabled"]="senza orario", ["ui.estimatedTimes"]="stimato, non ancora misurato", ["ui.setTerminusThis"]="Imposta come capolinea", ["ui.setTerminusAll"]="Imposta come capolinea per tutte le linee qui", ["ui.setTerminusHint"]="Il capolinea ancora l'orario e la sosta dei veicoli; qui gli autobus vengono ritirati.", ["ui.buttonTooltip"]="Orari dei trasporti", ["ui.panelTitle"]="PARTENZE", ["ui.panelHint"]="Seleziona una fermata per vedere le partenze di ogni linea da essa. Per modificare l'orario di una linea, seleziona la linea — i suoi controlli si trovano nel pannello informazioni della linea.", },
                ["ja-JP"] = new Dictionary<string, string> { ["ui.terminusNone"]="この路線には終点が設定されていないため、時刻表はルート上の最初の停留所に固定されています。この路線が通る停留所を選んで終点に設定すると、車両が発車時刻まで待機する場所を指定できます。", ["ui.terminusLost"]="この路線の終点はもうルート上にないため、時刻表は最初の停留所に戻っています。この路線が通る停留所を選んで、終点に設定してください。", ["opt.ManageVehicleCount.L"]="車両数を管理", ["opt.ManageVehicleCount.D"]="オンのとき（既定）、この Mod は時刻表を設定した各路線の車両数を調整し、指定した運行間隔を維持します。オフにすると、車両数の管理はあなた自身や他の車両編成 Mod（All Transit + Truck など）に委ねられます。Mod は終点での発車を引き続き制御しますが、バスの追加や変更は行いません。車両数が足りない路線は、設定した間隔より広い間隔で運行されます。", ["opt.CleanUninstall.L"]="このセーブデータからModのデータをすべて削除", ["opt.CleanUninstall.W"]="この都市にあるすべての路線の時刻表を完全に削除し、各路線をゲーム標準の動作に戻します。路線ごとの発車時刻、カスタムピーク時間帯、測定済みの所要時間データは失われ、元に戻すことはできません。\n\n重要: 確認後はこのメニューを閉じ、ゲームを少しのあいだ必ず進行させてから、セーブしてください。クリーンアップは次のシミュレーションステップで実行されるため、一時停止したままセーブすると、都市は変更されないまま保存されてしまいます。\n\n続行しますか？", ["opt.CleanUninstall.D"]="Modをきれいにアンインストールするための1回限りのクリーンアップです。すべての路線をバニラ状態に戻し（待機中のバスを解放し、分散係数を元に戻し、Modが設定した車両数を解除します）、この都市からModの保存データ（路線ごとの時刻表、カスタムピーク、測定済みの所要時間）を削除します。これを押したあと、ゲームを少しのあいだ進行させ（クリーンアップは次のシミュレーションステップで実行されるため、一時停止中は何も起こりません）、それから必ずセーブしてください。そのあとであれば、残留データを一切残さずにModを削除できます。時刻表が消去されるため、実行前に確認を求めます。Modを入れたまま押しても害はありません。路線が単にバニラの状態に戻るだけです。", ["opt.MaxDwellRoad.L"]="最大停車時間 — バス（発車時刻から何分まで）", ["opt.MaxDwellRoad.D"]="すでに乗車を始めている乗客のために、バスが掲示された発車時刻を過ぎてどれだけ待てるかです。これは目標ではなく上限です。乗車する人がいないバスは掲示された時刻ちょうどに発車し、この設定によって1秒でも遅れることはありません。この設定があるのは、ゲーム標準では車両に向かって歩き始めた時点でその人が乗客として数えられるためで、時刻どおりに強制発車させると、まだ乗り場を横切っている最中の人が全員、また待機列に戻されてしまいます。そこで車両はその人たちを待ちますが、待つのはここで指定した時間までです。デフォルトは3分です。0にすると、誰も待たずに時刻ちょうどに発車します。注意: これはゲーム標準の乗車受付時間を短くすることで機能するため、ゲームが本来待つ時間より長く車両を待たせることは決してできません。また、ゲーム内の1日を長くするModを使用している場合、ここでの最も大きな値には到達できないことがあります。", ["opt.MaxDwellRail.L"]="最大停車時間 — 列車、地下鉄、トラム（発車時刻から何分まで）", ["opt.MaxDwellRail.D"]="鉄道系に対する同じ上限で、こちらもデフォルトは3分です。混雑した駅のホームに人が溜まっているのが見えたら、この値を上げてください。ホームいっぱいの乗客を入れ替える列車や地下鉄は、バスよりもはるかに乗降に時間がかかり、乗客は自分が乗る車両に向かってホーム上に散らばり、しかもバスと違って停車駅をスキップすることが一切できません。この余裕はすべての停車駅に適用される点に注意してください。長い路線で大きな値にすると、一周のあいだに積み重なっていきます。また停車時間が長くなれば実際の一周時間も長くなるため、同じ運行間隔を維持するのに路線はより多くの車両を必要とします。バス側の値と同様、これはゲーム標準の乗車受付時間を延ばすのではなく短くするものなので、低速時間Modの下では最も大きな値には到達できないことがあります。", ["opt.RealisticTravelTime.L"]="リアルな移動時間（表示時刻を補正）", ["opt.RealisticTravelTime.D"]="路線の所要時間に関するゲーム内の推定値は、実際にシミュレートされる周回時間を過小評価します。バスは停留所ごとに加速・減速しますが、推定値はこれを無視しています（停留所の少ない路線で実測約1.7倍、停留所の多い路線で最大約2.5倍）。これをオンにすると、Modが各路線の実際の周回時間を計測し、リアルな停留所時刻を掲示するため、時刻表が実際のバスの動きと一致します。費用はかかりません。時刻を正確にするだけです。デフォルトはオフで、有効にするまで既存の時刻表は変更されません。", ["opt.ProvisionRealFleet.L"]="実際の移動時間に合わせて車両を配備（車両数が増加します）", ["opt.ProvisionRealFleet.D"]="各路線の車両数も、推定値ではなく実際の周回時間に合わせて算出します。費用が発生するのはこの設定です。実際の周回時間が推定値の約2倍になる路線で運行間隔を詰めて維持するには、およそ2倍の車両と2倍の維持費が必要です。オフ（デフォルト）では推定値に基づく車両数のままとなり、路線は設定した運行間隔よりも実質的に長い間隔で静かに運行されます。オンにすると実際の周回時間に合わせて配備します。増加のみ（推定値を下回って削減することはありません）で、上限も設けられているため、誤った計測値が大量のバスを送り込むことはありません。", ["ui.vehNotOnTimetable"]="まだ時刻表に登録されていません。始発停留所に最初に到着した時点で時刻表が割り当てられます。", ["ui.vehHolding"]="{at} の発車時刻までここで待機しています。", ["ui.vehAtStopLate"]="この停留所で、{at} の発車予定より {n} 分遅れています。", ["ui.vehAtStop"]="この停留所で、{at} に発車します。", ["ui.vehNextStop"]="次の停留所の予定時刻は {at} です。", ["ui.vehBehind"]="{n} 分遅れています。次の停留所の予定時刻は {at} でした。", ["ui.vehRefining"]="この路線は実際の所要時間を測定中のため、これらの時刻は変動します。", ["ui.rttOffWarning"]="リアルな所要時間がオフのため、表示時刻は測定された所要時間ではなくゲームの推定値を使用しています。測定値を使うにはMODのオプションでオンにしてください。", ["ui.loopMeasuring"]="実際の所要時間を測定中です（{need} 周中 {laps} 周）。", ["ui.loopRefining"]="実際の所要時間は約 {real} 分、調整中です（{need2} 周中 {wlaps} 周）。", ["ui.loopMeasured"]="実際の所要時間は {real} 分、測定済み（推定 {est} 分の {corr} 倍）。", ["ui.countMayRise"]="この台数は意図的に控えめで、測定完了後に増える場合があります。", ["ui.sizingSoon"]="所要時間の推定値が安定し次第、この路線の車両数を決めます。", ["ui.notSetByMod"]="この運行間隔には約{n}両が必要です。このModは車両数を設定していません。", ["ui.provisioning"]="そのために約{n}両を配備しています。", ["ui.realLoopEstimated"]="実際の一周は約{real}分（{est}分という推定値の{corr}倍、推定）。", ["ui.realLoopMeasured"]="実際の一周は約{real}分（{est}分という推定値の{corr}倍、実測）。", ["enum.VehicleCounts.HandsOff"]="Modに決めさせない", ["enum.VehicleCounts.ModDecides"]="Modに決めさせる", ["ui.noticeAsk"]="リアルな所要時間をオンに戻しますか？表示時刻が実際の路線に合うようになり、路線の車両数もそれに応じて増える場合があります。", ["opt.VehicleCounts.L"]="車両数", ["opt.VehicleCounts.D"]="時刻表を設定した各路線が何両を走らせるかを、誰が決めるかです。「Modに決めさせる」（推奨）は、路線を一周するのに実際どれだけかかるかを計測して車両数を決め、設定した運行間隔を維持できるようにします。特に手を加える必要はありません。このモードでは、時刻表を設定したすべての路線の車両数をModが管理します。ゲーム内の割り当て車両数のスライダーは保持されません。Modが自分の値を再適用するためです。「Modに決めさせない」はすべての路線を返し、以後いっさい車両数に触れません。あなた自身または車両管理専用のModが管理できます。発車時刻までの待機動作はどちらでも同じです。ある路線が想定より多くの車両を必要とする場合は、その路線の運行間隔を広げてください。それが本来の調整方法です。", ["ui.noticeTitle"]="リアルな所要時間はオフです", ["ui.noticeBody"]="これまで本MODは常に各路線の実際の所要時間を測定し、その値を表示時刻と車両数の両方に使用していました。現在はそれぞれ別の設定になり、どちらも初期状態ではオフのため、この都市はゲーム標準の推定値を使用しています。", ["ui.noticeWhere"]="この設定はオプションの「リアリズム」からいつでも変更できます。", ["ui.noticeKeep"]="オンにする", ["ui.noticeOff"]="オフのままにする", ["opt.StopAtEveryStop.L"]="すべての停留所で停車（空の停留所でも）", ["opt.StopAtEveryStop.D"]="デフォルトでは、Cities: Skylines II は待っている人も降りる人もいない停留所をバスがスキップすることを許可しています。減速して通過するだけなので、その停留所では予定の発車時刻まで待機せず、バスが時刻表より先行して運行してしまいます。この設定に関わらず、終点は常に停車が強制されるようになりました（スキップすると時刻表全体が破綻するため）。これをオンにすると、時刻表のある路線のすべての停留所でバスが必ず停車するようになり、掲示されたすべての時刻が守られます。ただし空の停留所ごとに短い停車時間が発生するため、路線の運行はやや遅くなります。バスなどの道路車両にのみ影響します。列車、トラム、船舶、航空機はすでにすべての駅で停車します。デフォルトはオフです。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 低速時間との互換性 — RT や Time2Work を使用する場合はオンに（ALPHA）", ["opt.RealisticTripsCompat.D"]="デフォルトはオフです。ゲーム内の1日を長くするMod（Time2Work / \"Realistic Trips\" など）を使用していない限り、オフのままにしてください。そのようなModと併用してこれをオンにすると、発車時刻・停留所時刻・車両数が先行せず正しく保たれます。Modが実際の1日の長さを自動的に計測します。低速時間Modがなければこの設定は何もせず、この設定がオフのときにModがそれを検出した場合はログに記録します。注意: この互換パスはALPHAであり、Realistic Trips とのゲーム内での動作検証はまだ行われていません。おかしな点があれば報告してください。Realistic Trips 使用時、路線は以前より正しく少ない車両数で運行されます。", ["opt.MorningPeakStart.L"]="朝ピークの開始", ["opt.MorningPeakStart.D"]="朝ピークの運行水準が始まる時刻。", ["opt.MorningPeakEnd.L"]="朝ピークの終了", ["opt.MorningPeakEnd.D"]="朝ピークの運行水準が終わる時刻。", ["opt.EveningPeakStart.L"]="夕ピークの開始", ["opt.EveningPeakStart.D"]="夕ピークの運行水準が始まる時刻。", ["opt.EveningPeakEnd.L"]="夕ピークの終了", ["opt.EveningPeakEnd.D"]="夕ピークの運行水準が終わる時刻。", ["opt.NightStart.L"]="夜間の開始", ["opt.NightStart.D"]="夜間運行が始まる時刻（深夜0時をまたぐ場合があります）。", ["opt.NightEnd.L"]="夜間の終了", ["opt.NightEnd.D"]="夜間運行が終わる時刻。", ["opt.Enabled.L"]="TransitTimetables を有効化", ["opt.Enabled.D"]="Mod全体のマスタースイッチ。オフ = 完全にバニラ状態: すべての路線の管理が停止し（待機中のバスは解放され、Modが適用した車両数と分散係数は元に戻ります）、路線ごとの時刻表は保持されるため再有効化すれば再開されます。デフォルトはオンです。", ["grp.GroupWindows"]="ピーク時間帯", ["grp.GroupCompat"]="互換性", ["grp.GroupStops"]="停留所", ["grp.GroupGeneral"]="全般", ["ui.to"]="〜", ["ui.timetable"]="時刻表", ["ui.on"]="オン", ["ui.off"]="オフ", ["ui.ttNow"]="現在 {i}分間隔 · {f}台", ["ui.ttNext"]="次: {n}", ["ui.firstDeparture"]="始発", ["ui.peakInterval"]="ピーク", ["ui.offPeakInterval"]="オフピーク", ["ui.otherHours"]="その他の時間帯", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="カスタムピーク（この路線）", ["ui.morningPeak"]="朝ピーク", ["ui.eveningPeak"]="夕ピーク", ["ui.customPeakInterval"]="カスタムピーク間隔", ["ui.terminusHint"]="停留所を選択すると発車時刻が表示され、その停留所をこの路線の終点に設定できます。", ["ui.noLines"]="この停留所を通る路線はありません。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終点", ["ui.departs"]="発車: {d}", ["ui.noDepartures"]="発車予定なし", ["ui.notTimetabled"]="時刻表なし", ["ui.estimatedTimes"]="推定値（未計測）", ["ui.setTerminusThis"]="終点に設定", ["ui.setTerminusAll"]="ここのすべての路線の終点に設定", ["ui.setTerminusHint"]="終点は時刻表と車両の待機を固定します。バスはここで退役します。", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="発車", ["ui.panelHint"]="停留所を選択すると、その停留所からの全路線の発車時刻が表示されます。路線の時刻表を編集するには路線を選択してください。操作項目は路線の情報パネルにあります。", },
                ["ko-KR"] = new Dictionary<string, string> { ["ui.terminusNone"]="이 노선에는 종점이 설정되어 있지 않아 시간표가 경로의 첫 번째 정류장을 기준으로 만들어집니다. 이 노선이 지나는 정류장을 선택한 뒤 종점으로 설정하면 차량이 출발을 기다릴 곳을 정할 수 있습니다.", ["ui.terminusLost"]="이 노선의 종점이 더 이상 경로에 없어 시간표가 첫 번째 정류장으로 되돌아갔습니다. 이 노선이 지나는 정류장을 선택한 뒤 종점으로 설정하세요.", ["opt.ManageVehicleCount.L"]="차량 수 관리", ["opt.ManageVehicleCount.D"]="켜면(기본값) 이 모드가 시간표가 설정된 각 노선의 차량 수를 조정하여 지정한 배차 간격을 유지합니다. 끄면 차량 수 관리는 사용자 또는 다른 차량 관리 모드(All Transit + Truck 등)에 맡겨집니다. 모드는 종점에서의 출발을 계속 제어하지만 버스를 추가하거나 변경하지는 않습니다. 차량이 너무 적은 노선은 설정한 간격보다 더 넓은 간격으로 운행됩니다.", ["opt.CleanUninstall.L"]="이 저장 파일에서 모드 데이터를 모두 제거", ["opt.CleanUninstall.W"]="이 도시의 모든 노선 시간표를 완전히 삭제하고, 모든 노선을 기본 게임의 동작으로 되돌립니다. 노선별 출발 시각, 사용자 지정 첨두 시간대, 측정된 이동 데이터가 사라지며 복구할 수 없습니다.\n\n꼭 기억하세요: 확인한 뒤에는 이 메뉴를 닫고 게임을 반드시 잠시 진행시킨 다음 저장하세요. 정리는 다음 시뮬레이션 단계에서 이루어지므로, 일시 정지 상태로 저장하면 도시가 그대로 저장됩니다.\n\n계속할까요?", ["opt.CleanUninstall.D"]="깨끗한 제거를 위한 일회성 정리입니다. 모든 노선을 기본 게임 상태로 되돌리고(대기 중이던 버스를 해제하고, 뭉침 방지를 복원하며, 모드가 정한 차량 대수를 더는 적용하지 않습니다) 이 도시에서 모드가 저장한 데이터(노선별 시간표, 사용자 지정 첨두, 측정된 이동 데이터)를 제거합니다. 이 버튼을 누른 다음 게임을 잠시 진행시키고(정리는 다음 시뮬레이션 단계에서 이루어지므로 일시 정지 상태에서는 아무 일도 일어나지 않습니다), 그다음 반드시 저장하세요 — 그 뒤에는 아무 잔여물도 남기지 않고 모드를 제거할 수 있습니다. 시간표가 모두 지워지므로 먼저 확인을 요청합니다. 모드를 그대로 설치해 둔 채 눌러도 해롭지 않습니다 — 노선이 그냥 완전한 기본 게임 상태로 돌아갈 뿐입니다.", ["opt.MaxDwellRoad.L"]="최대 정차 시간 — 버스 (출발 시각 이후 분)", ["opt.MaxDwellRoad.D"]="이미 승차를 시작한 승객을 위해 버스가 게시된 출발 시각을 넘겨 얼마나 더 기다릴 수 있는지 정합니다. 목표치가 아니라 한계치입니다: 승차하는 사람이 없는 버스는 게시된 그 시각에 정확히 출발하며, 이 설정이 그 출발을 단 1초도 늦추는 일은 없습니다. 이 설정이 필요한 이유는 기본 게임이 누군가 차량을 향해 걷기 시작하는 순간부터 그 사람을 승객으로 세기 때문입니다. 그래서 시각에 맞춰 무조건 출발시키면 아직 승강장을 건너오고 있던 사람들이 전부 다시 대기열로 밀려납니다. 이제는 차량이 그들을 기다리되, 이 시간을 넘겨서까지 기다리지는 않습니다. 기본값은 3분입니다. 0으로 설정하면 정시에 출발하고 아무도 기다리지 않습니다. 참고: 이 기능은 기본 게임이 원래 허용하는 승차 시간을 줄이는 방식으로 작동하므로, 게임이 기다렸을 시간보다 차량을 더 오래 기다리게 만드는 일은 결코 없습니다 — 그리고 게임 내 하루 길이를 늘리는 모드를 사용 중이라면 여기서 가장 높은 값에는 도달하지 못할 수도 있습니다.", ["opt.MaxDwellRail.L"]="최대 정차 시간 — 기차·지하철·트램 (출발 시각 이후 분)", ["opt.MaxDwellRail.D"]="철도에 적용되는 같은 한계치이며, 기본값은 마찬가지로 3분입니다. 붐비는 승강장에 사람이 쌓이는 것이 보이면 값을 올리세요: 기차나 지하철이 승강장을 가득 채운 사람들을 한꺼번에 태우고 내리는 데는 버스보다 훨씬 오래 걸리고, 승객들은 각자의 객차로 가려고 승강장을 따라 흩어지며, 버스와 달리 역을 건너뛸 수도 없습니다. 이 여유 시간은 모든 역에 적용되므로, 긴 노선에서 넉넉한 값을 주면 한 바퀴 도는 동안 그만큼 쌓인다는 점을 염두에 두세요 — 그리고 정차가 길어지면 실제 순환 시간도 길어지므로, 같은 배차 간격을 유지하려면 그 노선에 더 많은 차량이 필요해집니다. 버스 값과 마찬가지로 이 설정은 기본 게임이 원래 허용하는 승차 시간을 늘리는 것이 아니라 줄이는 방식이므로, 시간을 느리게 만드는 모드에서는 가장 높은 값에 도달하지 못할 수도 있습니다.", ["opt.RealisticTravelTime.L"]="현실적인 이동 시간 (게시 시각 보정)", ["opt.RealisticTravelTime.D"]="게임이 자체적으로 추정하는 노선 소요 시간은 실제 시뮬레이션되는 순환 시간보다 짧게 나옵니다 — 버스는 정류장마다 가속하고 제동하는데, 추정치는 이를 무시합니다 (실측 결과 정류장이 드문 노선은 약 1.7배, 정류장이 조밀한 노선은 약 2.5배까지 차이가 납니다). 이 옵션을 켜면 모드가 각 노선의 실제 순환 시간을 측정하여 현실적인 정류장 시각을 게시하므로, 시간표가 버스의 실제 운행과 일치합니다. 비용은 들지 않으며 — 시계를 정직하게 만들 뿐입니다. 기본값은 꺼짐이며, 켜기 전까지 기존 시간표는 변경되지 않습니다.", ["opt.ProvisionRealFleet.L"]="실제 이동 시간에 맞춰 차량 배치 (차량 수 증가)", ["opt.ProvisionRealFleet.D"]="추정치가 아니라 실제 순환 시간에 맞춰 각 노선의 차량 대수를 산정합니다. 비용이 드는 것은 바로 이 옵션입니다: 실제 순환 시간이 추정치의 약 2배인 노선에서 촘촘한 배차 간격을 유지하려면 차량이 약 2배, 유지비도 약 2배가 필요합니다. 꺼짐(기본값)은 추정 기반 대수를 유지하므로, 노선이 설정한 것보다 사실상 더 긴 배차 간격으로 조용히 운행됩니다. 켜면 실제 순환 시간에 맞춰 배치합니다. 증가 전용이며 — 추정치보다 노선 대수를 절대 줄이지 않습니다 — 상한이 걸려 있어 잘못된 측정값이 버스를 과도하게 늘리지 않습니다.", ["ui.vehNotOnTimetable"]="아직 시간표에 등록되지 않았습니다. 종점에 처음 도착할 때 시간표를 배정받습니다.", ["ui.vehHolding"]="예정 출발 시각인 {at}까지 여기서 대기 중입니다.", ["ui.vehAtStopLate"]="이 정류장에서 {at} 출발 예정보다 {n}분 늦었습니다.", ["ui.vehAtStop"]="이 정류장에서 {at}에 출발합니다.", ["ui.vehNextStop"]="다음 정류장 예정 시각은 {at}입니다.", ["ui.vehBehind"]="{n}분 지연 중입니다. 다음 정류장은 {at}에 도착할 예정이었습니다.", ["ui.vehRefining"]="이 노선은 실제 순환 시간을 측정 중이므로 이 시각은 변경될 수 있습니다.", ["ui.rttOffWarning"]="사실적인 이동 시간이 꺼져 있어 표시 시각은 측정된 순환 시간 대신 게임의 추정값을 사용합니다. 측정된 시각을 사용하려면 모드 옵션에서 켜세요.", ["ui.loopMeasuring"]="실제 순환 시간을 측정 중입니다({need}바퀴 중 {laps}바퀴).", ["ui.loopRefining"]="실제 순환 시간은 약 {real}분이며 아직 조정 중입니다({need2}바퀴 중 {wlaps}바퀴).", ["ui.loopMeasured"]="실제 순환 시간은 {real}분으로 측정되었습니다(추정 {est}분의 {corr}배).", ["ui.countMayRise"]="이 대수는 의도적으로 보수적으로 산정되었으며 측정이 완료되면 늘어날 수 있습니다.", ["ui.sizingSoon"]="소요 시간 추정치가 안정되는 대로 이 노선의 차량 수를 정합니다.", ["ui.notSetByMod"]="이 배차 간격에는 약 {n}대가 필요합니다. 이 모드는 차량 수를 설정하지 않습니다.", ["ui.provisioning"]="이를 위해 약 {n}대를 배치하고 있습니다.", ["ui.realLoopEstimated"]="실제 순환 약 {real}분 ({est}분 추정치의 {corr}배, 추정됨).", ["ui.realLoopMeasured"]="실제 순환 약 {real}분 ({est}분 추정치의 {corr}배, 측정됨).", ["enum.VehicleCounts.HandsOff"]="모드가 결정하지 않도록", ["enum.VehicleCounts.ModDecides"]="모드가 결정하도록", ["ui.noticeAsk"]="사실적인 시간을 다시 켤까요? 표시 시각이 실제 노선과 맞춰지고, 노선의 차량 대수도 그에 맞춰 늘어날 수 있습니다.", ["opt.VehicleCounts.L"]="차량 수", ["opt.VehicleCounts.D"]="시간표가 설정된 각 노선이 몇 대의 차량을 운행할지 누가 결정할지 정합니다. \"모드가 결정하도록\"(권장)은 노선을 한 바퀴 도는 데 실제로 얼마나 걸리는지 측정해 차량 수를 정하므로, 설정한 배차 간격을 지킬 수 있고 따로 신경 쓸 필요가 없습니다. 이 모드에서는 시간표가 설정된 모든 노선의 차량 수를 모드가 관리합니다. 게임의 배정 차량 슬라이더는 유지되지 않습니다. 모드가 자체 값을 다시 적용하기 때문입니다. \"모드가 결정하지 않도록\"은 모든 노선을 되돌려주고 이후 차량 수에 전혀 관여하지 않으므로, 직접 또는 차량 관리 전용 모드가 담당할 수 있습니다. 출발 대기 동작은 두 경우 모두 동일합니다. 어떤 노선이 원하는 것보다 많은 차량을 요구한다면 그 노선의 배차 간격을 늘리세요. 그것이 진짜 조절 수단입니다.", ["ui.noticeTitle"]="사실적인 시간이 꺼져 있습니다", ["ui.noticeBody"]="지금까지 이 모드는 항상 각 노선의 실제 소요 시간을 측정해 표시 시각과 차량 대수 모두에 사용했습니다. 이제는 각각 별도의 설정이며 둘 다 기본적으로 꺼져 있어, 이 도시는 게임 자체의 추정값을 사용합니다.", ["ui.noticeWhere"]="옵션의 사실성 항목에서 언제든지 변경할 수 있습니다.", ["ui.noticeKeep"]="켜기", ["ui.noticeOff"]="끈 상태로 두기", ["opt.StopAtEveryStop.L"]="모든 정류장에 정차 (빈 정류장 포함)", ["opt.StopAtEveryStop.D"]="기본적으로 Cities: Skylines II는 기다리는 사람도, 내리려는 사람도 없는 정류장을 버스가 건너뛰도록 허용합니다 — 감속하며 통과만 하므로 그 정류장은 예정된 출발 시각까지 대기하지 않고, 버스가 시간표보다 앞서 운행할 수 있습니다. 이제 종점은 이 설정과 관계없이 항상 정차하도록 강제됩니다 (건너뛰면 전체 시간표가 어긋납니다). 이 옵션을 켜면 시간표가 적용된 노선의 모든 정류장에 버스가 진입하여 정차하도록 강제하므로 게시된 모든 시각이 지켜집니다 — 빈 정류장마다 잠시 정차하는 대가로 노선이 조금 느려집니다. 버스와 기타 도로 차량에만 영향을 주며, 기차·트램·선박·항공기는 이미 모든 역에 정차합니다. 기본값은 꺼짐입니다.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 느린 시간 호환 — RT나 Time2Work을 사용하면 켜세요 (알파)", ["opt.RealisticTripsCompat.D"]="기본값은 꺼짐 — 게임 내 하루 길이를 늘리는 모드(Time2Work / \"Realistic Trips\" 등)를 사용하지 않는 한 꺼진 채로 두세요. 그런 모드와 함께 이 옵션을 켜면 출발 시각, 정류장 시각, 차량 대수가 앞서 운행하지 않고 정확하게 유지됩니다. 모드가 실제 하루 길이를 자동으로 측정합니다. 느린 시간 모드가 없으면 이 설정은 아무 효과가 없으며, 이 옵션이 꺼진 상태에서 그런 모드가 감지되면 로그에 기록됩니다. 참고: 이 호환 경로는 알파이며 아직 게임 내에서 Realistic Trips와 함께 테스트되지 않았습니다 — 이상한 점이 있으면 제보해 주세요. Realistic Trips에서는 노선이 이전보다 올바르게 더 적은 차량을 사용합니다.", ["opt.MorningPeakStart.L"]="오전 첨두 시작", ["opt.MorningPeakStart.D"]="오전 첨두 운행 수준이 시작되는 시각입니다.", ["opt.MorningPeakEnd.L"]="오전 첨두 종료", ["opt.MorningPeakEnd.D"]="오전 첨두 운행 수준이 끝나는 시각입니다.", ["opt.EveningPeakStart.L"]="오후 첨두 시작", ["opt.EveningPeakStart.D"]="오후 첨두 운행 수준이 시작되는 시각입니다.", ["opt.EveningPeakEnd.L"]="오후 첨두 종료", ["opt.EveningPeakEnd.D"]="오후 첨두 운행 수준이 끝나는 시각입니다.", ["opt.NightStart.L"]="야간 시작", ["opt.NightStart.D"]="야간 운행이 시작되는 시각입니다 (자정을 넘길 수 있음).", ["opt.NightEnd.L"]="야간 종료", ["opt.NightEnd.D"]="야간 운행이 끝나는 시각입니다.", ["opt.Enabled.L"]="TransitTimetables 활성화", ["opt.Enabled.D"]="모드 전체의 주 스위치입니다. 꺼짐 = 완전한 기본 게임: 모든 노선의 관리가 중단되고(대기 중이던 버스는 해제되며 모드가 적용한 차량 대수와 뭉침 방지 계수가 되돌려집니다), 다시 켜면 이어갈 수 있도록 노선별 시간표는 유지됩니다. 기본값은 켜짐입니다.", ["grp.GroupWindows"]="첨두 시간대", ["grp.GroupCompat"]="호환성", ["grp.GroupStops"]="정류장", ["grp.GroupGeneral"]="일반", ["ui.to"]="~", ["ui.timetable"]="시간표", ["ui.on"]="켜짐", ["ui.off"]="꺼짐", ["ui.ttNow"]="현재 {i}분 간격 · 차량 {f}대", ["ui.ttNext"]="다음: {n}", ["ui.firstDeparture"]="첫차 출발", ["ui.peakInterval"]="첨두", ["ui.offPeakInterval"]="비첨두", ["ui.otherHours"]="그 외 시간", ["ui.nightInterval"]="야간", ["ui.customLinePeak"]="사용자 지정 첨두 (이 노선)", ["ui.morningPeak"]="오전 첨두", ["ui.eveningPeak"]="오후 첨두", ["ui.customPeakInterval"]="사용자 지정 첨두 간격", ["ui.terminusHint"]="정류장을 선택하면 출발 시각을 확인하고 이 노선의 종점으로 설정할 수 있습니다.", ["ui.noLines"]="이 정류장을 지나는 노선이 없습니다.", ["ui.line"]="{n}번 노선", ["ui.terminusBadge"]="종점", ["ui.departs"]="출발: {d}", ["ui.noDepartures"]="예정된 출발 없음", ["ui.notTimetabled"]="시간표 미설정", ["ui.estimatedTimes"]="추정치, 아직 측정되지 않음", ["ui.setTerminusThis"]="종점으로 설정", ["ui.setTerminusAll"]="여기의 모든 노선을 종점으로 설정", ["ui.setTerminusHint"]="종점은 시간표와 차량 대기의 기준점이며, 버스는 이곳에서 퇴역합니다.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="출발 시각", ["ui.panelHint"]="정류장을 선택하면 그 정류장의 모든 노선 출발 시각을 볼 수 있습니다. 노선의 시간표를 편집하려면 노선을 선택하세요 — 관련 설정은 노선의 정보 패널에 있습니다.", },
                ["pl-PL"] = new Dictionary<string, string> { ["ui.terminusNone"]="Dla tej linii nie ustawiono przystanku krańcowego, więc rozkład jazdy opiera się na pierwszym przystanku na trasie. Wybierz przystanek obsługiwany przez tę linię i ustaw go jako krańcowy, aby zdecydować, gdzie pojazdy czekają na swój odjazd.", ["ui.terminusLost"]="Przystanek krańcowy tej linii nie znajduje się już na jej trasie, więc rozkład jazdy opiera się teraz na pierwszym przystanku. Wybierz przystanek obsługiwany przez tę linię i ustaw go jako krańcowy.", ["opt.ManageVehicleCount.L"]="Zarządzaj liczbą pojazdów", ["opt.ManageVehicleCount.D"]="Gdy opcja jest włączona (domyślnie), mod ustawia liczbę pojazdów każdej linii z rozkładem jazdy tak, aby utrzymać wybrany odstęp między kursami. Wyłącz ją, aby pozostawić liczbę pojazdów Tobie lub innemu modowi flotowemu (np. All Transit + Truck) – mod nadal wstrzymuje odjazdy na przystanku końcowym, po prostu nie dodaje ani nie zmienia autobusów. Linia z niewystarczającą liczbą pojazdów będzie wtedy kursować z większym odstępem niż ustawiony.", ["opt.CleanUninstall.L"]="Usuń wszystkie dane moda z tego zapisu gry", ["opt.CleanUninstall.W"]="Spowoduje to USUNIĘCIE rozkładu jazdy każdej linii w tym mieście i przywrócenie wszystkim liniom zachowania z gry podstawowej. Twoje godziny odjazdów poszczególnych linii, własne okna szczytu i zmierzone czasy przejazdu zostaną utracone i nie da się ich odzyskać.\n\nWAŻNE: po potwierdzeniu zamknij to menu i pozwól grze przez chwilę DZIAŁAĆ, a potem zapisz. Czyszczenie następuje w kolejnym kroku symulacji, więc zapisanie gry na pauzie zachowałoby miasto bez zmian.\n\nKontynuować?", ["opt.CleanUninstall.D"]="Jednorazowe czyszczenie przed czystym odinstalowaniem moda. Cofa każdą linię do stanu z gry podstawowej (zwalnia wstrzymane autobusy, przywraca rozgęszczanie, usuwa ustawioną przez mod liczbę pojazdów) i usuwa zapisane dane moda z tego miasta (twoje rozkłady jazdy poszczególnych linii, własne szczyty i zmierzone czasy przejazdu). Naciśnij ten przycisk, potem pozwól grze przez chwilę działać (czyszczenie następuje w kolejnym kroku symulacji, więc na pauzie nic się nie dzieje), a potem ZAPISZ — po tym mod można usunąć bez żadnych pozostałości. Kasuje twoje rozkłady jazdy, więc najpierw prosi o potwierdzenie. Naciśnięcie go przy nadal zainstalowanym modzie jest nieszkodliwe — linie po prostu wracają do zwykłego zachowania z gry podstawowej.", ["opt.MaxDwellRoad.L"]="Maksymalny czas postoju — autobusy (minuty po godzinie odjazdu)", ["opt.MaxDwellRoad.D"]="Jak długo autobus może czekać po podanej godzinie odjazdu na pasażerów, którzy JUŻ wsiadają. To limit, a nie cel: autobus, do którego nikt nie wsiada, i tak odjeżdża dokładnie o swojej podanej minucie, a to ustawienie nigdy nie opóźnia go ani o sekundę. Istnieje dlatego, że gra podstawowa uznaje kogoś za pasażera już w chwili, gdy ten zaczyna iść do pojazdu, więc odjazd bez czekania odesłałby z powrotem do kolejki wszystkich, którzy wciąż idą przez peron. Teraz pojazd na nich czeka, ale nigdy dłużej niż przez ten czas. Domyślnie 3 minuty. Ustaw 0, aby odjeżdżać punktualnie co do minuty i nie czekać na nikogo. Uwaga: działa to przez skrócenie własnego okna wsiadania gry podstawowej, więc nigdy nie sprawi, że pojazd będzie czekał DŁUŻEJ, niż zrobiłaby to gra — a jeśli używasz moda wydłużającego dobę w grze, najwyższe wartości mogą być nieosiągalne.", ["opt.MaxDwellRail.L"]="Maksymalny czas postoju — pociągi, metro i tramwaje (minuty po godzinie odjazdu)", ["opt.MaxDwellRail.D"]="Ten sam limit dla kolei, również domyślnie 3 minuty. Zwiększ go, jeśli widzisz ludzi gromadzących się na ruchliwym peronie: pociąg lub metro, które wymienia pasażerów z całego pełnego peronu, potrzebuje na to znacznie więcej czasu niż autobus, jego pasażerowie rozchodzą się wzdłuż peronu do swoich wagonów, a w przeciwieństwie do autobusu nigdy nie może pominąć przystanku. Pamiętaj, że ten zapas obowiązuje na każdym przystanku, więc duża wartość na długiej linii sumuje się na całej pętli — a dłuższe postoje oznaczają dłuższy rzeczywisty obieg, więc linia będzie potrzebowała więcej pojazdów, aby utrzymać ten sam odstęp. Podobnie jak przy wartości dla autobusów, skraca to własne okno wsiadania gry podstawowej, zamiast je wydłużać, więc przy modzie spowalniającym czas najwyższe wartości mogą być nieosiągalne.", ["opt.RealisticTravelTime.L"]="Realistyczny czas przejazdu (koryguje podane godziny)", ["opt.RealisticTravelTime.D"]="Wbudowana w grę ocena czasu przejazdu linii jest zaniżona wobec rzeczywistej, symulowanej pętli — autobusy przyspieszają i hamują na każdym przystanku, czego ta ocena nie uwzględnia (zmierzone na żywo: około 1,7x na liniach z rzadkimi przystankami, do ~2,5x na liniach z gęstymi przystankami). Włącz tę opcję, a mod zmierzy rzeczywistą pętlę każdej linii i poda realistyczne godziny odjazdów, aby tablica odpowiadała temu, co faktycznie robią autobusy. Nic nie kosztuje — tylko sprawia, że zegar mówi prawdę. Domyślnie wyłączone; istniejące rozkłady jazdy pozostają bez zmian, dopóki tego nie włączysz.", ["opt.ProvisionRealFleet.L"]="Dostosuj flotę do rzeczywistego czasu przejazdu (zwiększa liczbę pojazdów)", ["opt.ProvisionRealFleet.D"]="Dobiera również liczbę pojazdów każdej linii do jej RZECZYWISTEJ pętli, a nie do szacunku. To właśnie ta opcja generuje koszty: utrzymanie krótkiego odstępu na linii, której rzeczywista pętla jest ~2x dłuższa od szacunku, wymaga około dwukrotnie więcej pojazdów i dwukrotnie wyższych kosztów utrzymania. Wyłączona (domyślnie) zachowuje liczbę pojazdów opartą na szacunku, więc linia po cichu kursuje z dłuższym faktycznym odstępem niż ustawiony; włączona dostosowuje tabor do rzeczywistej pętli. Tylko zwiększa — nigdy nie schodzi poniżej szacunku — i ma limit, więc błędny pomiar nie zaleje cię autobusami.", ["ui.vehNotOnTimetable"]="Jeszcze nie w rozkładzie. Pojazd otrzymuje rozkład, gdy po raz pierwszy dotrze do pętli.", ["ui.vehHolding"]="Czeka tutaj do {at}, planowego odjazdu.", ["ui.vehAtStopLate"]="Na tym przystanku, {n} min po planowym odjeździe o {at}.", ["ui.vehAtStop"]="Na tym przystanku, odjazd o {at}.", ["ui.vehNextStop"]="Następny przystanek planowo o {at}.", ["ui.vehBehind"]="{n} min opóźnienia. Następny przystanek był planowany na {at}.", ["ui.vehRefining"]="Ta linia wciąż mierzy swój rzeczywisty czas obiegu, więc te godziny jeszcze się zmienią.", ["ui.rttOffWarning"]="Realistyczny czas przejazdu jest WYŁĄCZONY, więc podane godziny korzystają z szacunku gry zamiast ze zmierzonego obiegu. Włącz go w opcjach moda, aby używać zmierzonych czasów.", ["ui.loopMeasuring"]="Rzeczywisty czas obiegu jest wciąż mierzony ({laps} z {need} okrążeń).", ["ui.loopRefining"]="Rzeczywisty obieg to około {real} min, wciąż doprecyzowywany ({wlaps} z {need2} okrążeń).", ["ui.loopMeasured"]="Rzeczywisty obieg to {real} min, zmierzony ({corr}x szacunku {est} min).", ["ui.countMayRise"]="Ta liczba jest celowo ostrożna i może wzrosnąć po zakończeniu pomiaru.", ["ui.sizingSoon"]="Ta linia zostanie dobrana, gdy tylko szacunek czasu przejazdu się ustabilizuje.", ["ui.notSetByMod"]="Ten odstęp wymaga ~{n} pojazdów. Ten mod nie ustala ich liczby.", ["ui.provisioning"]="Zapewniono na to ~{n} pojazdów.", ["ui.realLoopEstimated"]="Rzeczywista pętla ~{real} min ({corr}x szacunku {est} min, szacowane).", ["ui.realLoopMeasured"]="Rzeczywista pętla ~{real} min ({corr}x szacunku {est} min, zmierzone).", ["enum.VehicleCounts.HandsOff"]="Niech mod nie decyduje", ["enum.VehicleCounts.ModDecides"]="Niech decyduje mod", ["ui.noticeAsk"]="Włączyć z powrotem realistyczne czasy? Podane godziny będą wtedy zgodne z trasą, a liczba pojazdów linii może odpowiednio wzrosnąć.", ["opt.VehicleCounts.L"]="Liczba pojazdów", ["opt.VehicleCounts.D"]="Kto decyduje, ile pojazdów kursuje na każdej linii z rozkładem. \"Niech decyduje mod\" (zalecane) dobiera liczbę pojazdów, mierząc, ile naprawdę trwa pokonanie trasy, dzięki czemu linia może utrzymać ustawiony odstęp, i nie wymaga uwagi. W tym trybie mod zarządza liczbą na wszystkich liniach z rozkładem: suwak przypisanych pojazdów z gry nie zostanie zachowany, ponieważ mod ponownie stosuje własną wartość. \"Niech mod nie decyduje\" zwraca wszystkie linie i nigdy więcej nie rusza liczby, więc ty lub dedykowany mod flotowy możecie nią zarządzać. Wstrzymywanie odjazdów działa tak samo w obu przypadkach. Jeśli linia potrzebuje więcej pojazdów, niż chcesz, zwiększ jej odstęp; to jest właściwe pokrętło.", ["ui.noticeTitle"]="Realistyczne czasy są wyłączone", ["ui.noticeBody"]="Do tej pory ten mod zawsze mierzył, ile naprawdę trwa trasa każdej linii, i używał tego zarówno do podanych godzin, jak i do liczby pojazdów. Teraz są to dwa osobne ustawienia i oba są początkowo wyłączone, więc to miasto korzysta z szacunku gry.", ["ui.noticeWhere"]="Możesz to zmienić w dowolnej chwili w Opcjach, w sekcji Realizm.", ["ui.noticeKeep"]="Włącz je", ["ui.noticeOff"]="Zostaw wyłączone", ["opt.StopAtEveryStop.L"]="Zatrzymuj na każdym przystanku (nawet pustym)", ["opt.StopAtEveryStop.D"]="Domyślnie Cities: Skylines II pozwala autobusowi POMINĄĆ przystanek, na którym nikt nie czeka i nikt nie chce wysiąść — jedynie zwalnia i przejeżdża, więc taki przystanek nigdy nie jest wstrzymywany do planowego odjazdu i autobus może wyprzedzić swój rozkład jazdy. Przystanek krańcowy jest teraz zawsze zmuszony do zatrzymania, niezależnie od tego ustawienia (jego pominięcie rozstroiłoby cały rozkład). Włącz tę opcję, aby zmusić autobusy do zatrzymania się na KAŻDYM przystanku linii z rozkładem jazdy, tak by każda podana godzina była dotrzymana — kosztem krótkiego postoju na każdym pustym przystanku, przez co linie kursują nieco wolniej. Dotyczy wyłącznie autobusów i innych pojazdów drogowych; pociągi, tramwaje, statki i samoloty i tak zatrzymują się na każdej stacji. Domyślnie wyłączone.", ["opt.RealisticTripsCompat.L"]="Zgodność z Realistic Trips / spowolnionym czasem — włącz, jeśli używasz RT lub Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Domyślnie wyłączone — zostaw wyłączone, chyba że używasz moda wydłużającego dobę w grze (Time2Work / \"Realistic Trips\" lub podobnego). Włącz z takim modem, a odjazdy, godziny na przystankach i wielkości taboru pozostaną poprawne zamiast kursować przed czasem; mod automatycznie mierzy rzeczywistą długość doby. Bez moda spowalniającego czas to ustawienie nic nie robi, a jeśli mod wykryje taki mod, gdy ta opcja jest wyłączona, odnotuje to w dzienniku. UWAGA: ta ścieżka zgodności jest w wersji ALPHA i NIE została jeszcze przetestowana z Realistic Trips w grze — zgłaszaj wszelkie nieprawidłowości. Pod Realistic Trips twoje linie będą poprawnie używać mniej pojazdów niż wcześniej.", ["opt.MorningPeakStart.L"]="Początek porannego szczytu", ["opt.MorningPeakStart.D"]="Godzina, o której zaczyna się poranny poziom obsługi szczytowej.", ["opt.MorningPeakEnd.L"]="Koniec porannego szczytu", ["opt.MorningPeakEnd.D"]="Godzina, o której kończy się poranny poziom obsługi szczytowej.", ["opt.EveningPeakStart.L"]="Początek wieczornego szczytu", ["opt.EveningPeakStart.D"]="Godzina, o której zaczyna się wieczorny poziom obsługi szczytowej.", ["opt.EveningPeakEnd.L"]="Koniec wieczornego szczytu", ["opt.EveningPeakEnd.D"]="Godzina, o której kończy się wieczorny poziom obsługi szczytowej.", ["opt.NightStart.L"]="Początek nocy", ["opt.NightStart.D"]="Godzina, o której zaczyna się obsługa nocna (może przekraczać północ).", ["opt.NightEnd.L"]="Koniec nocy", ["opt.NightEnd.D"]="Godzina, o której kończy się obsługa nocna.", ["opt.Enabled.L"]="Włącz TransitTimetables", ["opt.Enabled.D"]="Główny przełącznik całego moda. Wyłączony = dokładnie jak w grze podstawowej: każda linia przestaje być zarządzana (wszystkie wstrzymane autobusy są zwalniane, a zastosowana przez mod liczba pojazdów i współczynnik rozgęszczania zostają cofnięte), przy czym twoje rozkłady jazdy poszczególnych linii są zachowane, aby ponowne włączenie je wznowiło. Domyślnie włączony.", ["grp.GroupWindows"]="Okna szczytu", ["grp.GroupCompat"]="Zgodność", ["grp.GroupStops"]="Przystanki", ["grp.GroupGeneral"]="Ogólne", ["ui.to"]="do", ["ui.timetable"]="ROZKŁAD JAZDY", ["ui.on"]="WŁ.", ["ui.off"]="WYŁ.", ["ui.ttNow"]="teraz co {i} min · {f} pojazdów", ["ui.ttNext"]="następny: {n}", ["ui.firstDeparture"]="Pierwszy odjazd", ["ui.peakInterval"]="Szczyt", ["ui.offPeakInterval"]="Poza szczytem", ["ui.otherHours"]="pozostałe godziny", ["ui.nightInterval"]="Noc", ["ui.customLinePeak"]="Własny szczyt (ta linia)", ["ui.morningPeak"]="Poranny szczyt", ["ui.eveningPeak"]="Wieczorny szczyt", ["ui.customPeakInterval"]="Własny odstęp w szczycie", ["ui.terminusHint"]="Wybierz przystanek, aby zobaczyć jego odjazdy i ustawić go jako przystanek krańcowy tej linii.", ["ui.noLines"]="Żadna linia nie obsługuje tego przystanku.", ["ui.line"]="Linia {n}", ["ui.terminusBadge"]="krańcowy", ["ui.departs"]="odjazd: {d}", ["ui.noDepartures"]="brak zaplanowanych odjazdów", ["ui.notTimetabled"]="brak rozkładu jazdy", ["ui.estimatedTimes"]="szacowane, jeszcze niezmierzone", ["ui.setTerminusThis"]="Ustaw jako krańcowy", ["ui.setTerminusAll"]="Ustaw jako krańcowy dla wszystkich linii tutaj", ["ui.setTerminusHint"]="Przystanek krańcowy wyznacza rozkład jazdy i wstrzymanie pojazdów; autobusy są tu wycofywane.", ["ui.buttonTooltip"]="Rozkłady jazdy komunikacji", ["ui.panelTitle"]="ODJAZDY", ["ui.panelHint"]="Wybierz przystanek, aby zobaczyć odjazdy wszystkich linii z tego miejsca. Aby edytować rozkład jazdy linii, wybierz linię — jej ustawienia znajdują się w panelu informacyjnym linii.", },
                ["pt-BR"] = new Dictionary<string, string> { ["ui.terminusNone"]="Nenhum terminal foi definido para esta linha, então a tabela de horários está ancorada na primeira parada da rota. Selecione uma parada que esta linha atende e defina-a como terminal para escolher onde os veículos aguardam a sua partida.", ["ui.terminusLost"]="O terminal desta linha não está mais na rota dela, então a tabela de horários voltou para a primeira parada. Selecione uma parada que esta linha atende e defina-a como terminal.", ["opt.ManageVehicleCount.L"]="Gerenciar o número de veículos", ["opt.ManageVehicleCount.D"]="Quando ativado (padrão), o mod ajusta o número de veículos de cada linha com horário para manter o intervalo que você escolher. Desative para deixar o número de veículos por sua conta ou de outro mod de frota (como All Transit + Truck) — o mod continua segurando as partidas no terminal, apenas não adiciona nem altera ônibus. Uma linha com poucos veículos passa então a circular com um intervalo maior do que o definido.", ["opt.CleanUninstall.L"]="Remover todos os dados do mod deste jogo salvo", ["opt.CleanUninstall.W"]="Isso vai APAGAR a tabela de horários de todas as linhas desta cidade e devolver todas as linhas ao comportamento do jogo original. Seus horários de partida por linha, os picos personalizados e os dados de trajeto medidos serão perdidos e não poderão ser recuperados.\n\nIMPORTANTE: depois de confirmar, feche este menu e deixe o jogo RODAR por um instante, e depois salve. A limpeza acontece no próximo passo da simulação, então salvar com o jogo pausado salvaria a sua cidade sem alteração alguma.\n\nContinuar?", ["opt.CleanUninstall.D"]="Limpeza única para uma desinstalação limpa. Reverte todas as linhas ao jogo original (libera os ônibus retidos, restaura o fator de dispersão, descarta o número de veículos definido pelo mod) e remove os dados salvos do mod desta cidade (suas tabelas de horários por linha, os picos personalizados e os trajetos medidos). Pressione este botão, depois deixe o jogo rodar por um instante (a limpeza acontece no próximo passo da simulação, então não faz nada com o jogo pausado) e então SALVE — depois disso o mod pode ser removido sem deixar nenhum resíduo. Ele apaga as suas tabelas de horários, por isso pede confirmação antes. É inofensivo pressioná-lo com o mod ainda instalado — as linhas simplesmente voltam ao jogo original puro.", ["opt.MaxDwellRoad.L"]="Tempo máximo de parada — ônibus (minutos após o horário de partida)", ["opt.MaxDwellRoad.D"]="Por quanto tempo um ônibus pode continuar esperando além da sua partida programada por passageiros que JÁ estão embarcando. É um limite, não uma meta: um ônibus sem ninguém embarcando parte exatamente no minuto programado, e esta configuração nunca o atrasa nem um segundo. Ela existe porque o jogo original conta alguém como passageiro no momento em que a pessoa começa a caminhar até o veículo, então sair no horário a qualquer custo jogaria de volta para a fila todo mundo que ainda estivesse atravessando a plataforma. Agora o veículo espera por essas pessoas, mas nunca mais do que isso. Padrão: 3 minutos. Defina 0 para partir no minuto exato e não esperar ninguém. Nota: isso funciona encurtando a própria janela de embarque do jogo original, então nunca pode fazer um veículo esperar MAIS do que o jogo faria — e se você usar um mod que alongue o dia do jogo, os valores mais altos aqui podem não ser alcançáveis.", ["opt.MaxDwellRail.L"]="Tempo máximo de parada — trens, metrôs e bondes (minutos após o horário de partida)", ["opt.MaxDwellRail.D"]="O mesmo limite para os veículos sobre trilhos, também 3 minutos por padrão. Aumente o limite se você vir gente se acumulando em uma plataforma movimentada: um trem ou metrô que troca os passageiros de uma plataforma cheia leva muito mais tempo para carregar do que um ônibus, seus passageiros se espalham ao longo da plataforma para chegar ao próprio vagão e, ao contrário de um ônibus, ele nunca pode pular uma parada. Tenha em mente que essa folga vale em cada parada, então um valor generoso em uma linha longa vai se somando ao longo da volta — e paradas mais longas significam uma volta real mais longa, então a linha vai querer mais veículos para manter o mesmo intervalo. Assim como no valor dos ônibus, isso encurta a própria janela de embarque do jogo original em vez de estendê-la, então sob um mod de tempo lento os valores mais altos podem não ser alcançáveis.", ["opt.RealisticTravelTime.L"]="Tempo de viagem realista (corrige os horários exibidos)", ["opt.RealisticTravelTime.D"]="A própria estimativa do jogo sobre quanto tempo uma linha leva subestima o trajeto real simulado — os ônibus aceleram e freiam em cada parada, algo que a estimativa ignora (medido ao vivo em cerca de 1,7x em linhas com poucas paradas e até ~2,5x nas com muitas paradas). Ative esta opção e o mod mede o trajeto real de cada linha e exibe horários de parada realistas, para que o quadro corresponda ao que os ônibus realmente fazem. Não custa nada — só torna o relógio honesto. Desativado por padrão; as tabelas de horários existentes não mudam até você ativá-lo.", ["opt.ProvisionRealFleet.L"]="Dimensionar a frota pelo tempo de viagem real (aumenta o número de veículos)", ["opt.ProvisionRealFleet.D"]="Também dimensiona a quantidade de veículos de cada linha pelo trajeto REAL em vez da estimativa. Esta é a opção que gasta: manter um intervalo curto em uma linha cujo trajeto real é ~2x a estimativa exige cerca do dobro de veículos, e o dobro de manutenção. Desativado (padrão) mantém a contagem baseada na estimativa, então uma linha roda silenciosamente com um intervalo efetivo maior do que você definiu; ativado dimensiona para o trajeto real. Apenas cresce — nunca reduz uma linha abaixo da estimativa — e é limitado, para que uma leitura ruim não inunde você de ônibus.", ["ui.vehNotOnTimetable"]="Ainda não está na tabela de horários. Ele recebe seu horário ao chegar ao terminal pela primeira vez.", ["ui.vehHolding"]="Aguardando aqui até {at}, sua partida programada.", ["ui.vehAtStopLate"]="Nesta parada, {n} min atrasado em relação à partida das {at}.", ["ui.vehAtStop"]="Nesta parada, partindo às {at}.", ["ui.vehNextStop"]="Próxima parada prevista para {at}.", ["ui.vehBehind"]="{n} min atrasado. A próxima parada estava prevista para {at}.", ["ui.vehRefining"]="Esta linha ainda está medindo seu percurso real, então esses horários vão mudar.", ["ui.rttOffWarning"]="O tempo de viagem realista está DESLIGADO, então os horários usam a estimativa do jogo em vez deste percurso medido. Ative-o nas Opções do mod para usar os tempos medidos.", ["ui.loopMeasuring"]="O percurso real ainda está sendo medido ({laps} de {need} voltas).", ["ui.loopRefining"]="Percurso real de cerca de {real} min, ainda sendo ajustado ({wlaps} de {need2} voltas).", ["ui.loopMeasured"]="Percurso real de {real} min, medido ({corr}x a estimativa de {est} min).", ["ui.countMayRise"]="Esse número é deliberadamente cauteloso e pode aumentar quando a medição terminar.", ["ui.sizingSoon"]="Esta linha será dimensionada assim que sua estimativa de duração se estabilizar.", ["ui.notSetByMod"]="Este intervalo precisa de ~{n} veículos. Este mod não está definindo o número.", ["ui.provisioning"]="Estão sendo fornecidos ~{n} veículos para isso.", ["ui.realLoopEstimated"]="Volta real ~{real} min ({corr}x a estimativa de {est} min, estimada).", ["ui.realLoopMeasured"]="Volta real ~{real} min ({corr}x a estimativa de {est} min, medida).", ["enum.VehicleCounts.HandsOff"]="Não deixar o mod decidir", ["enum.VehicleCounts.ModDecides"]="Deixar o mod decidir", ["ui.noticeAsk"]="Ligar novamente os horários realistas? Os horários passarão a corresponder ao trajeto, e o número de veículos de uma linha pode aumentar junto.", ["opt.VehicleCounts.L"]="Número de veículos", ["opt.VehicleCounts.D"]="Quem decide quantos veículos cada linha com horário opera. \"Deixar o mod decidir\" (recomendado) dimensiona cada linha medindo quanto tempo o percurso realmente leva, para que ela consiga manter o intervalo definido, e não exige atenção. Nesse modo o mod controla o número em todas as linhas com horário: o controle de veículos atribuídos do jogo não será mantido, porque o mod reaplica o próprio valor. \"Não deixar o mod decidir\" devolve todas as linhas e nunca mais mexe no número, para que você ou um mod dedicado a frotas possa cuidar disso. As esperas de partida funcionam igual nos dois casos. Se uma linha pedir mais veículos do que você quer, aumente o intervalo dela; esse é o controle de verdade.", ["ui.noticeTitle"]="Os horários realistas estão desligados", ["ui.noticeBody"]="Até agora, este mod sempre media quanto tempo o trajeto de cada linha realmente leva e usava esse valor tanto para os horários exibidos quanto para o número de veículos. Agora são duas configurações separadas e ambas começam desligadas, então esta cidade usa a estimativa do próprio jogo.", ["ui.noticeWhere"]="Você pode mudar isso a qualquer momento nas Opções, em Realismo.", ["ui.noticeKeep"]="Ligar", ["ui.noticeOff"]="Deixar desligados", ["opt.StopAtEveryStop.L"]="Parar em cada parada (mesmo nas vazias)", ["opt.StopAtEveryStop.D"]="Por padrão, Cities: Skylines II permite que um ônibus PULE uma parada onde ninguém está esperando e ninguém quer descer — ele apenas desacelera e passa, então essa parada nunca é retida até o horário programado de partida e o ônibus pode adiantar-se à sua tabela de horários. O terminal agora é sempre forçado a parar, independentemente desta configuração (pulá-lo desmontaria toda a programação). Ative esta opção para forçar os ônibus a encostar e parar em CADA parada de uma linha com tabela de horários, para que cada horário exibido seja cumprido — ao custo de uma breve espera em cada parada vazia, o que deixa as linhas um pouco mais lentas. Afeta apenas ônibus e outros veículos rodoviários; trens, bondes, navios e aeronaves já param em todas as estações. Desativado por padrão.", ["opt.RealisticTripsCompat.L"]="Compatibilidade com Realistic Trips / tempo lento — ative se você usa RT ou Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desativado por padrão — deixe desativado a menos que você use um mod que alongue o dia do jogo (Time2Work / \"Realistic Trips\" ou similar). Ative-o com um mod desses e as partidas, horários de parada e tamanhos de frota permanecem corretos em vez de rodar adiantados; o mod mede automaticamente a duração real do dia. Sem um mod de tempo lento esta configuração não faz nada, e se o mod detectar um enquanto isto estiver desativado ele registrará no log. NOTA: este caminho de compatibilidade é ALFA e ainda NÃO foi testado com o Realistic Trips em jogo — por favor, relate qualquer coisa estranha. Sob o Realistic Trips suas linhas usarão corretamente menos veículos do que antes.", ["opt.MorningPeakStart.L"]="Início do pico da manhã", ["opt.MorningPeakStart.D"]="Hora em que começa o nível de serviço do pico da manhã.", ["opt.MorningPeakEnd.L"]="Fim do pico da manhã", ["opt.MorningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da manhã.", ["opt.EveningPeakStart.L"]="Início do pico da noite", ["opt.EveningPeakStart.D"]="Hora em que começa o nível de serviço do pico da noite.", ["opt.EveningPeakEnd.L"]="Fim do pico da noite", ["opt.EveningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da noite.", ["opt.NightStart.L"]="Início da madrugada", ["opt.NightStart.D"]="Hora em que começa o serviço noturno (pode passar da meia-noite).", ["opt.NightEnd.L"]="Fim da madrugada", ["opt.NightEnd.D"]="Hora em que termina o serviço noturno.", ["opt.Enabled.L"]="Ativar TransitTimetables", ["opt.Enabled.D"]="Interruptor mestre de todo o mod. Desativado = jogo original exato: todas as linhas deixam de ser gerenciadas (qualquer ônibus retido é liberado e a contagem de frota e o fator de dispersão aplicados pelo mod são revertidos), enquanto suas tabelas de horários por linha são mantidas para que reativar as retome. Ativado por padrão.", ["grp.GroupWindows"]="Janelas de pico", ["grp.GroupCompat"]="Compatibilidade", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="Geral", ["ui.to"]="às", ["ui.timetable"]="TABELA DE HORÁRIOS", ["ui.on"]="LIGADO", ["ui.off"]="DESLIGADO", ["ui.ttNow"]="agora a cada {i} min · {f} veículos", ["ui.ttNext"]="próxima: {n}", ["ui.firstDeparture"]="Primeira partida", ["ui.peakInterval"]="Pico", ["ui.offPeakInterval"]="Fora de pico", ["ui.otherHours"]="outros horários", ["ui.nightInterval"]="Madrugada", ["ui.customLinePeak"]="Pico personalizado (esta linha)", ["ui.morningPeak"]="Pico da manhã", ["ui.eveningPeak"]="Pico da noite", ["ui.customPeakInterval"]="Intervalo de pico personalizado", ["ui.terminusHint"]="Selecione uma parada para ver suas partidas e defini-la como o terminal desta linha.", ["ui.noLines"]="Nenhuma linha atende esta parada.", ["ui.line"]="Linha {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nenhuma partida programada", ["ui.notTimetabled"]="sem tabela de horários", ["ui.estimatedTimes"]="estimado, ainda não medido", ["ui.setTerminusThis"]="Definir como terminal", ["ui.setTerminusAll"]="Definir como terminal para todas as linhas aqui", ["ui.setTerminusHint"]="O terminal ancora a programação e a retenção de veículos; os ônibus se aposentam aqui.", ["ui.buttonTooltip"]="Tabelas de Horários do Transporte", ["ui.panelTitle"]="PARTIDAS", ["ui.panelHint"]="Selecione uma parada para ver as partidas de todas as linhas a partir dela. Para editar a tabela de horários de uma linha, selecione a linha — seus controles estão no painel de informações da linha.", },
                ["ru-RU"] = new Dictionary<string, string> { ["ui.terminusNone"]="Для этого маршрута не назначена конечная станция, поэтому расписание привязано к первой остановке маршрута. Выберите остановку, которую обслуживает этот маршрут, и назначьте её конечной, чтобы задать, где транспорт ожидает своего отправления.", ["ui.terminusLost"]="Конечная станция этого маршрута больше не входит в его маршрут следования, поэтому расписание вернулось к первой остановке. Выберите остановку, которую обслуживает этот маршрут, и назначьте её конечной.", ["opt.ManageVehicleCount.L"]="Управлять количеством транспорта", ["opt.ManageVehicleCount.D"]="Когда включено (по умолчанию), мод задаёт количество транспорта на каждом маршруте с расписанием, чтобы выдерживать выбранный вами интервал движения. Отключите, чтобы оставить количество транспорта на ваше усмотрение или на управление другого мода для автопарка (например, All Transit + Truck) — мод по-прежнему удерживает отправления на конечной остановке, он просто не добавляет и не меняет автобусы. Маршрут со слишком малым числом транспортных средств тогда будет ходить с интервалом больше заданного.", ["opt.CleanUninstall.L"]="Удалить все данные мода из этого сохранения", ["opt.CleanUninstall.W"]="Это УДАЛИТ расписание каждого маршрута в этом городе и вернёт все маршруты к поведению базовой игры. Заданное вами время отправления по каждому маршруту, собственные окна часа пик и измеренные данные о времени в пути будут потеряны, и восстановить их будет невозможно.\n\nВАЖНО: после подтверждения закройте это меню и дайте игре немного ПОРАБОТАТЬ, а затем сохранитесь. Очистка происходит на следующем шаге симуляции, поэтому, сохранившись на паузе, вы сохраните город в неизменном виде.\n\nПродолжить?", ["opt.CleanUninstall.D"]="Разовая очистка для чистого удаления мода. Возвращает каждый маршрут к оригинальному поведению (отпускает удержанные автобусы, восстанавливает разгруппировку, сбрасывает заданное модом количество транспорта) и удаляет сохранённые данные мода из этого города (ваши расписания по маршрутам, собственные часы пик и измеренное время в пути). Нажмите эту кнопку, затем дайте игре немного поработать (очистка происходит на следующем шаге симуляции, поэтому на паузе она ничего не делает), а затем СОХРАНИТЕСЬ — после этого мод можно удалить, не оставив никаких следов. Она стирает ваши расписания, поэтому сначала запрашивает подтверждение. Ничего страшного, если нажать её, когда мод ещё установлен, — маршруты просто вернутся к обычному оригинальному поведению.", ["opt.MaxDwellRoad.L"]="Максимальное время стоянки — автобусы (минут сверх времени отправления)", ["opt.MaxDwellRoad.D"]="Сколько автобус может ждать сверх указанного времени отправления ради пассажиров, которые УЖЕ садятся. Это ограничение, а не цель: автобус, в который никто не садится, всё равно отправляется точно в указанную минуту, и этот параметр не задерживает его ни на секунду. Он нужен потому, что базовая игра считает человека пассажиром с того момента, как он начинает идти к транспорту, поэтому жёсткое отправление отбросило бы всех, кто ещё идёт через платформу, обратно в очередь. Теперь транспорт их дожидается, но не дольше указанного здесь значения. По умолчанию 3 минуты. Задайте 0, чтобы отправляться минута в минуту и никого не ждать. Примечание: это работает за счёт сокращения собственного окна посадки базовой игры, поэтому параметр никогда не заставит транспорт ждать ДОЛЬШЕ, чем это сделала бы игра — а если вы используете мод, удлиняющий игровой день, самые высокие значения здесь могут оказаться недостижимыми.", ["opt.MaxDwellRail.L"]="Максимальное время стоянки — поезда, метро и трамваи (минут сверх времени отправления)", ["opt.MaxDwellRail.D"]="Такое же ограничение для рельсового транспорта, по умолчанию тоже 3 минуты. Увеличьте его, если видите, что люди скапливаются на загруженной платформе: поезд или метро, которые высаживают и забирают целую платформу пассажиров, грузятся куда дольше автобуса, их пассажиры распределяются вдоль платформы, чтобы попасть в свой вагон, и, в отличие от автобуса, они никогда не могут пропустить остановку. Учтите, что этот запас действует на каждой остановке, поэтому щедрое значение на длинном маршруте набегает за весь круг — а более долгие стоянки означают более долгий реальный круг, поэтому маршруту потребуется больше транспорта, чтобы выдерживать тот же интервал. Как и в случае со значением для автобусов, это сокращает собственное окно посадки базовой игры, а не удлиняет его, поэтому при моде замедления времени самые высокие значения могут оказаться недостижимыми.", ["opt.RealisticTravelTime.L"]="Реалистичное время в пути (корректировка расписания)", ["opt.RealisticTravelTime.D"]="Собственная оценка игры о продолжительности маршрута занижает реальный, смоделированный круг — автобусы разгоняются и тормозят на каждой остановке, что оценка не учитывает (замерено вживую примерно 1,7x на редких маршрутах и до ~2,5x на маршрутах с частыми остановками). Включите этот параметр, и мод замерит реальный круг каждого маршрута и покажет реалистичное время на остановках, чтобы табло совпадало с тем, что автобусы делают на самом деле. Ничего не стоит — просто делает часы честными. По умолчанию ВЫКЛ; существующие расписания не меняются, пока вы это не включите.", ["opt.ProvisionRealFleet.L"]="Планировать парк по реальному времени в пути (увеличивает число транспортных средств)", ["opt.ProvisionRealFleet.D"]="Также рассчитывать количество транспорта каждого маршрута по РЕАЛЬНОМУ кругу, а не по оценке. Именно этот параметр тратит деньги: удержание плотного интервала на маршруте, чей реальный круг ~2x от оценки, требует примерно вдвое больше транспорта и вдвое больше расходов на содержание. ВЫКЛ (по умолчанию) сохраняет количество по оценке, поэтому маршрут незаметно ходит с более длинным фактическим интервалом, чем вы задали; ВКЛ планирует под реальный круг. Только увеличивает — никогда не урезает маршрут ниже оценки — и ограничено, так что ошибочный замер не завалит вас автобусами.", ["ui.vehNotOnTimetable"]="Ещё не в расписании. Транспорт получает расписание, когда впервые прибывает на конечную остановку.", ["ui.vehHolding"]="Ожидает здесь до {at}, времени отправления по расписанию.", ["ui.vehAtStopLate"]="На этой остановке, отставание {n} мин от отправления в {at}.", ["ui.vehAtStop"]="На этой остановке, отправление в {at}.", ["ui.vehNextStop"]="Следующая остановка по расписанию в {at}.", ["ui.vehBehind"]="Отставание {n} мин от расписания. Следующая остановка была запланирована на {at}.", ["ui.vehRefining"]="Эта линия ещё измеряет реальное время круга, поэтому это время будет меняться.", ["ui.rttOffWarning"]="Реалистичное время в пути ВЫКЛЮЧЕНО, поэтому в расписании используется оценка игры, а не измеренное время круга. Включите его в настройках мода, чтобы использовать измеренные значения.", ["ui.loopMeasuring"]="Реальное время круга ещё измеряется ({laps} из {need} кругов).", ["ui.loopRefining"]="Реальное время круга около {real} мин, уточняется ({wlaps} из {need2} кругов).", ["ui.loopMeasured"]="Реальное время круга {real} мин, измерено ({corr}x от оценки в {est} мин).", ["ui.countMayRise"]="Это количество намеренно занижено и может увеличиться после завершения измерений.", ["ui.sizingSoon"]="Линия будет рассчитана, как только оценка длительности станет стабильной.", ["ui.notSetByMod"]="Этому интервалу нужно ~{n} машин. Этот мод не задаёт их количество.", ["ui.provisioning"]="Для этого выделяется ~{n} машин.", ["ui.realLoopEstimated"]="Реальный круг ~{real} мин ({corr}x от оценки в {est} мин, оценка).", ["ui.realLoopMeasured"]="Реальный круг ~{real} мин ({corr}x от оценки в {est} мин, измерено).", ["enum.VehicleCounts.HandsOff"]="Пусть мод не решает", ["enum.VehicleCounts.ModDecides"]="Пусть решает мод", ["ui.noticeAsk"]="Снова включить реалистичное время? Расписание будет соответствовать маршруту, а количество транспорта на линии может соответственно вырасти.", ["opt.VehicleCounts.L"]="Количество транспорта", ["opt.VehicleCounts.D"]="Кто определяет, сколько машин работает на каждой линии с расписанием. \"Пусть решает мод\" (рекомендуется) подбирает количество, измеряя, сколько на самом деле занимает круг линии, чтобы она выдерживала заданный интервал, и не требует внимания. В этом режиме мод управляет количеством на всех линиях с расписанием: игровой ползунок назначенных машин не сохранится, поскольку мод заново применяет собственное значение. \"Пусть мод не решает\" возвращает все линии и больше никогда не трогает количество, так что им можете управлять вы или специализированный мод. Задержка отправления работает одинаково в обоих случаях. Если линия требует больше машин, чем вам хотелось бы, увеличьте её интервал; это и есть настоящий рычаг.", ["ui.noticeTitle"]="Реалистичное время отключено", ["ui.noticeBody"]="До сих пор этот мод всегда измерял, сколько на самом деле занимает маршрут каждой линии, и использовал это значение и для расписания, и для количества транспорта. Теперь это две отдельные настройки, и обе изначально отключены, поэтому город использует оценку самой игры.", ["ui.noticeWhere"]="Это можно изменить в любой момент в настройках мода, в разделе Реализм.", ["ui.noticeKeep"]="Включить", ["ui.noticeOff"]="Оставить отключёнными", ["opt.StopAtEveryStop.L"]="Останавливаться на каждой остановке (даже пустой)", ["opt.StopAtEveryStop.D"]="По умолчанию Cities: Skylines II позволяет автобусу ПРОПУСТИТЬ остановку, где никто не ждёт и никто не хочет выйти — он лишь притормаживает и проезжает, поэтому такая остановка никогда не удерживается до запланированного отправления, и автобус может идти с опережением расписания. Конечная станция теперь всегда принудительно требует остановки независимо от этого параметра (её пропуск сорвал бы всё расписание). Включите этот параметр, чтобы автобусы заезжали и останавливались на КАЖДОЙ остановке маршрута с расписанием, чтобы каждое указанное время соблюдалось — ценой короткой стоянки на каждой пустой остановке, из-за чего маршруты идут чуть медленнее. Затрагивает только автобусы и другой дорожный транспорт; поезда, трамваи, суда и самолёты и так останавливаются на каждой станции. По умолчанию ВЫКЛ.", ["opt.RealisticTripsCompat.L"]="Совместимость с Realistic Trips / замедлением времени — включите, если используете RT или Time2Work (АЛЬФА)", ["opt.RealisticTripsCompat.D"]="По умолчанию ВЫКЛ — оставьте выключенным, если только вы не используете мод, удлиняющий игровой день (Time2Work / \\\"Realistic Trips\\\" или подобный). Включите его вместе с таким модом, и отправления, время на остановках и размеры парка останутся корректными вместо опережения; мод автоматически замеряет реальную длину дня. Без мода замедления времени этот параметр ничего не делает, а если мод обнаружит такой при выключенном параметре, он отметит это в журнале. ПРИМЕЧАНИЕ: этот путь совместимости — АЛЬФА и пока НЕ тестировался с Realistic Trips в игре — сообщайте обо всём странном. При Realistic Trips ваши маршруты будут корректно использовать меньше транспорта, чем раньше.", ["opt.MorningPeakStart.L"]="Начало утреннего часа пик", ["opt.MorningPeakStart.D"]="Час, когда начинается уровень обслуживания утреннего часа пик.", ["opt.MorningPeakEnd.L"]="Конец утреннего часа пик", ["opt.MorningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания утреннего часа пик.", ["opt.EveningPeakStart.L"]="Начало вечернего часа пик", ["opt.EveningPeakStart.D"]="Час, когда начинается уровень обслуживания вечернего часа пик.", ["opt.EveningPeakEnd.L"]="Конец вечернего часа пик", ["opt.EveningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания вечернего часа пик.", ["opt.NightStart.L"]="Начало ночи", ["opt.NightStart.D"]="Час, когда начинается ночное обслуживание (может переходить за полночь).", ["opt.NightEnd.L"]="Конец ночи", ["opt.NightEnd.D"]="Час, когда заканчивается ночное обслуживание.", ["opt.Enabled.L"]="Включить TransitTimetables", ["opt.Enabled.D"]="Главный переключатель всего мода. Выкл = точно как в оригинале: все маршруты перестают управляться (любые удержанные автобусы отпускаются, а заданные модом количество транспорта и коэффициент разгруппировки возвращаются к исходным), при этом ваши расписания по маршрутам сохраняются, так что повторное включение их возобновит. По умолчанию ВКЛ.", ["grp.GroupWindows"]="Окна часа пик", ["grp.GroupCompat"]="Совместимость", ["grp.GroupStops"]="Остановки", ["grp.GroupGeneral"]="Общие", ["ui.to"]="до", ["ui.timetable"]="РАСПИСАНИЕ", ["ui.on"]="ВКЛ", ["ui.off"]="ВЫКЛ", ["ui.ttNow"]="сейчас каждые {i} мин · {f} ед. транспорта", ["ui.ttNext"]="далее: {n}", ["ui.firstDeparture"]="Первое отправление", ["ui.peakInterval"]="Час пик", ["ui.offPeakInterval"]="Вне часа пик", ["ui.otherHours"]="прочие часы", ["ui.nightInterval"]="Ночь", ["ui.customLinePeak"]="Свой час пик (этот маршрут)", ["ui.morningPeak"]="Утренний час пик", ["ui.eveningPeak"]="Вечерний час пик", ["ui.customPeakInterval"]="Свой интервал в час пик", ["ui.terminusHint"]="Выберите остановку, чтобы увидеть её отправления и назначить её конечной станцией этого маршрута.", ["ui.noLines"]="Эту остановку не обслуживают маршруты.", ["ui.line"]="Маршрут {n}", ["ui.terminusBadge"]="конечная", ["ui.departs"]="отправление: {d}", ["ui.noDepartures"]="отправления не запланированы", ["ui.notTimetabled"]="без расписания", ["ui.estimatedTimes"]="оценка, ещё не измерено", ["ui.setTerminusThis"]="Назначить конечной", ["ui.setTerminusAll"]="Назначить конечной для всех маршрутов здесь", ["ui.setTerminusHint"]="Конечная станция закрепляет расписание и удержание транспорта; здесь автобусы выводятся из эксплуатации.", ["ui.buttonTooltip"]="Расписания транспорта", ["ui.panelTitle"]="ОТПРАВЛЕНИЯ", ["ui.panelHint"]="Выберите остановку, чтобы увидеть отправления всех маршрутов от неё. Чтобы изменить расписание маршрута, выберите маршрут — его настройки находятся в информационной панели маршрута.", },
                ["zh-HANS"] = new Dictionary<string, string> { ["ui.terminusNone"]="本线路尚未设置终点站，因此时刻表锚定在路线上的第一个站点。请选择一个本线路停靠的站点并将其设为终点站，以决定车辆在哪里等待发车。", ["ui.terminusLost"]="本线路的终点站已不在其路线上，因此时刻表已改用路线上的第一个站点。请选择一个本线路停靠的站点并将其设为终点站。", ["opt.ManageVehicleCount.L"]="管理车辆数量", ["opt.ManageVehicleCount.D"]="开启时（默认），模组会为每条设有时刻表的线路设置车辆数量，以维持你所选的发车间隔。关闭后，车辆数量将交由你自己或其他车队模组（如 All Transit + Truck）来管理——模组仍会在终点站控制发车，只是不再增加或更改公交车。车辆过少的线路此时只会以大于设定值的间隔运行。", ["opt.CleanUninstall.L"]="移除本存档中的所有模组数据", ["opt.CleanUninstall.W"]="此操作将彻底删除本城市中每一条线路的时刻表，并让所有线路恢复到游戏原版的行为。你为各线路设置的发车时间、自定义高峰时段以及实测的行驶数据都将丢失，且无法恢复。\n\n重要提示：确认之后，请关闭此菜单，务必让游戏实际运行片刻，然后再保存。清理会在下一个模拟步骤中进行，因此在暂停状态下保存，只会把你的城市原封不动地存下来。\n\n是否继续？", ["opt.CleanUninstall.D"]="一次性清理，用于干净地卸载模组。它会把每条线路恢复为原版状态（放行被暂停的公交车、还原防聚集、撤销模组设置的车辆数量），并从本城市中移除模组保存的数据（你的各线路时刻表、自定义高峰和实测的行驶数据）。按下此项后，让游戏运行片刻（清理在下一个模拟步骤中进行，因此暂停时它什么也不会做），然后务必保存——在那之后就可以移除模组，不会留下任何残留。它会清空你的时刻表，因此会先请你确认。在模组仍然安装的情况下按下它也没有害处——线路只会回到纯粹的原版状态。", ["opt.MaxDwellRoad.L"]="最长停站时间——公交车（超出预定发车时间的分钟数）", ["opt.MaxDwellRoad.D"]="公交车在超过预定发车时间之后，还可以为已经开始上车的乘客继续等待多久。这是一个上限，不是目标：没有人上车的公交车仍会精确地在预定的那一分钟发车，此设置绝不会让它多等一秒。它之所以存在，是因为游戏自身会在一名市民刚开始走向车辆的那一刻就把他算作乘客，所以强行准点发车会把所有还在穿过站台的人重新赶回等待队列。现在车辆会等他们，但绝不会超过这个时长。默认 3 分钟。设为 0 则准点发车、不等任何人。注意：此项的实现方式是缩短游戏自身的上车窗口，因此它绝不可能让车辆等得比游戏原本更久——而且如果你使用了会延长游戏内一天时长的模组，这里最高的那些数值可能无法达到。", ["opt.MaxDwellRail.L"]="最长停站时间——火车、地铁和有轨电车（超出预定发车时间的分钟数）", ["opt.MaxDwellRail.D"]="轨道交通的同一项上限，默认同样为 3 分钟。如果你看到繁忙站台上的乘客越积越多，可以调高它：火车或地铁要与满满一站台的乘客完成上下车交换，装载耗时远比公交车长，乘客还会沿着站台散开去走向自己那节车厢，而且不同于公交车，它永远无法跳过某一站。请记住这个宽限在每一站都会生效，因此在长线路上，一个宽松的数值会在整圈里累积起来——而更长的停站时间意味着更长的实际环行时间，于是该线路要维持相同的发车间隔就会需要更多车辆。与公交车的数值一样，此项是缩短游戏自身的上车窗口，而不是延长它，因此在慢时间模组下，最高的那些数值可能无法达到。", ["opt.RealisticTravelTime.L"]="真实旅行时间（修正显示的时刻）", ["opt.RealisticTravelTime.D"]="游戏自身对线路运行时长的估算低于真实模拟的环线用时——公交车在每一站都要加速和刹车，而估算忽略了这一点（实测中，站点稀疏的线路约为 1.7 倍，站点密集的线路可达约 2.5 倍）。开启此项后，模组会测量每条线路的真实环线用时并给出真实的到站时刻，使显示牌与公交车实际运行相符。此项不产生任何花费——它只是让时刻表如实反映现实。默认关闭；在你启用之前，现有时刻表保持不变。", ["opt.ProvisionRealFleet.L"]="根据实际行驶时间配置车队（增加车辆数量）", ["opt.ProvisionRealFleet.D"]="同时按每条线路的真实环线用时（而非估算值）来确定其车辆数量。这一项会产生花费：要在真实环线约为估算值 2 倍的线路上维持紧凑的发车间隔，大约需要两倍的车辆和两倍的维护费。关闭（默认）沿用基于估算的车辆数，导致线路实际运行的发车间隔悄悄比你设定的更长；开启则按真实环线配备车辆。只增不减——绝不会把线路的车辆减到估算值以下——并且有上限，因此一次错误的读数不会让公交车泛滥成灾。", ["ui.vehNotOnTimetable"]="尚未加入时刻表。车辆首次到达终点站时才会获得时刻表。", ["ui.vehHolding"]="在此等待至 {at} 的预定发车时间。", ["ui.vehAtStopLate"]="停靠此站，比 {at} 的发车时间晚 {n} 分钟。", ["ui.vehAtStop"]="停靠此站，将于 {at} 发车。", ["ui.vehNextStop"]="下一站预定时间为 {at}。", ["ui.vehBehind"]="晚点 {n} 分钟。下一站原定时间为 {at}。", ["ui.vehRefining"]="该线路仍在测量实际环行时间，因此这些时间会有变动。", ["ui.rttOffWarning"]="真实旅行时间已关闭，因此显示的时间使用游戏自身的估算，而非测得的环行时间。请在模组选项中开启以使用实测时间。", ["ui.loopMeasuring"]="正在测量实际环行时间（已完成 {laps}/{need} 圈）。", ["ui.loopRefining"]="实际环行时间约 {real} 分钟，仍在校准（已完成 {wlaps}/{need2} 圈）。", ["ui.loopMeasured"]="实际环行时间为 {real} 分钟，已测得（为 {est} 分钟估算值的 {corr} 倍）。", ["ui.countMayRise"]="该数量为保守估计，测量完成后可能增加。", ["ui.sizingSoon"]="待该线路的时长估算稳定后即会配置车辆。", ["ui.notSetByMod"]="该发车间隔需要约 {n} 辆车。本模组不设置车辆数量。", ["ui.provisioning"]="为此配置约 {n} 辆车。", ["ui.realLoopEstimated"]="实际一圈约 {real} 分钟（是 {est} 分钟估算值的 {corr} 倍，估算）。", ["ui.realLoopMeasured"]="实际一圈约 {real} 分钟（是 {est} 分钟估算值的 {corr} 倍，实测）。", ["enum.VehicleCounts.HandsOff"]="不让模组决定", ["enum.VehicleCounts.ModDecides"]="让模组决定", ["ui.noticeAsk"]="要重新开启真实时间吗？显示时间将与实际线路一致，线路的车辆数量也可能相应增加。", ["opt.VehicleCounts.L"]="车辆数量", ["opt.VehicleCounts.D"]="由谁决定每条已设置时刻表的线路运行多少车辆。「让模组决定」（推荐）通过测量线路实际跑完一圈需要多久来配置车辆，使其能够维持你设定的发车间隔，无需额外关注。在此模式下，模组会掌管所有已设置时刻表线路的车辆数量：游戏自带的分配车辆滑块不会保留，因为模组会重新应用自己的数值。「不让模组决定」会交还所有线路，此后不再改动车辆数量，便于你自己或专门的车队模组接管。两种模式下的发车等待行为完全相同。如果某条线路所需的车辆超出你的预期，请调宽该线路的发车间隔，那才是真正的调节手段。", ["ui.noticeTitle"]="真实时间设置已关闭", ["ui.noticeBody"]="此前本模组始终会测量每条线路的实际行驶时间，并将其用于显示时间和车辆数量。现在它们是两项独立设置，且默认均为关闭，因此本城市使用的是游戏自身的估算值。", ["ui.noticeWhere"]="你可以随时在选项的「真实性」中更改。", ["ui.noticeKeep"]="开启", ["ui.noticeOff"]="保持关闭", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使无人的站点）", ["opt.StopAtEveryStop.D"]="默认情况下，《都市：天际线 II》允许公交车跳过既无人等候、也无人下车的站点——它只是减速驶过，因此该站点从不会被强制停靠到预定发车时间，公交车便可能提前于时刻表运行。现在无论此设置如何，终点站都始终强制停靠（跳过它会打乱整份时刻表）。开启此项可强制公交车在有时刻表的线路上驶入并停靠每一站，使每个显示的时刻都得到遵守——代价是在每个无人的站点短暂停留，使线路运行略慢一些。仅影响公交车及其他道路车辆；火车、有轨电车、船只和飞机本就在每一站停靠。默认关闭。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 慢时间兼容——若使用 RT 或 Time2Work 请开启（ALPHA）", ["opt.RealisticTripsCompat.D"]="默认关闭——除非你使用了会延长游戏内一天时长的模组（Time2Work / \"Realistic Trips\" 或类似模组），否则请保持关闭。搭配此类模组时开启，发车时间、到站时刻和车辆数量将保持正确而不会提前运行；模组会自动测量真实的一天时长。若未使用慢时间模组，此设置不起任何作用；若在此项关闭时检测到该类模组，将会在日志中记录提示。注意：此兼容路径为 ALPHA，尚未在游戏内针对 Realistic Trips 测试——如有异常请反馈。在 Realistic Trips 下，你的线路将正确地使用比以往更少的车辆。", ["opt.MorningPeakStart.L"]="早高峰开始", ["opt.MorningPeakStart.D"]="早高峰运营水平开始的时刻。", ["opt.MorningPeakEnd.L"]="早高峰结束", ["opt.MorningPeakEnd.D"]="早高峰运营水平结束的时刻。", ["opt.EveningPeakStart.L"]="晚高峰开始", ["opt.EveningPeakStart.D"]="晚高峰运营水平开始的时刻。", ["opt.EveningPeakEnd.L"]="晚高峰结束", ["opt.EveningPeakEnd.D"]="晚高峰运营水平结束的时刻。", ["opt.NightStart.L"]="夜间开始", ["opt.NightStart.D"]="夜间运营开始的时刻（可能跨过午夜）。", ["opt.NightEnd.L"]="夜间结束", ["opt.NightEnd.D"]="夜间运营结束的时刻。", ["opt.Enabled.L"]="启用 TransitTimetables", ["opt.Enabled.D"]="整个模组的总开关。关闭 = 完全原版：每条线路都不再被管理（任何被暂停的公交车都会放行，模组施加的车辆数和防聚集系数都会还原），同时保留你的各线路时刻表，以便重新启用时恢复。默认开启。", ["grp.GroupWindows"]="高峰时段", ["grp.GroupCompat"]="兼容性", ["grp.GroupStops"]="站点", ["grp.GroupGeneral"]="常规", ["ui.to"]="至", ["ui.timetable"]="时刻表", ["ui.on"]="开", ["ui.off"]="关", ["ui.ttNow"]="现每 {i} 分钟 · {f} 辆车", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班发车", ["ui.peakInterval"]="高峰", ["ui.offPeakInterval"]="平峰", ["ui.otherHours"]="其他时段", ["ui.nightInterval"]="夜间", ["ui.customLinePeak"]="自定义高峰（本线路）", ["ui.morningPeak"]="早高峰", ["ui.eveningPeak"]="晚高峰", ["ui.customPeakInterval"]="自定义高峰间隔", ["ui.terminusHint"]="选择一个站点以查看其发车时刻，并将其设为本线路的终点站。", ["ui.noLines"]="没有线路停靠此站点。", ["ui.line"]="线路 {n}", ["ui.terminusBadge"]="终点站", ["ui.departs"]="发车：{d}", ["ui.noDepartures"]="无预定发车", ["ui.notTimetabled"]="无时刻表", ["ui.estimatedTimes"]="预估值，尚未实测", ["ui.setTerminusThis"]="设为终点站", ["ui.setTerminusAll"]="设为此处所有线路的终点站", ["ui.setTerminusHint"]="终点站锚定时刻表和车辆暂停；公交车在此退役。", ["ui.buttonTooltip"]="公交时刻表", ["ui.panelTitle"]="发车", ["ui.panelHint"]="选择一个站点以查看每条线路从该站的发车时刻。要编辑某线路的时刻表，请选中该线路——其控件位于该线路的信息面板中。", },
                ["zh-HANT"] = new Dictionary<string, string> { ["ui.terminusNone"]="此路線尚未設定終點站，因此時刻表以路線上的第一個站點為錨點。選擇此路線行經的一個站點並將其設為終點站，即可決定車輛在何處等候發車。", ["ui.terminusLost"]="此路線的終點站已不在其路線上，因此時刻表已改以第一個站點為錨點。選擇此路線行經的一個站點並將其設為終點站。", ["opt.ManageVehicleCount.L"]="管理車輛數量", ["opt.ManageVehicleCount.D"]="開啟時（預設），模組會為每條設有時刻表的路線設定車輛數量，以維持你所選的發車間隔。關閉後，車輛數量將交由你自己或其他車隊模組（如 All Transit + Truck）來管理——模組仍會在終點站控制發車，只是不再增加或變更公車。車輛過少的路線此時只會以大於設定值的間隔運行。", ["opt.CleanUninstall.L"]="從此存檔移除所有模組資料", ["opt.CleanUninstall.W"]="這會徹底刪除本城市中每一條路線的時刻表，並讓所有路線回到原版遊戲的運作方式。你的各路線發車時刻、自訂尖峰時段與實測的行駛資料都會遺失，且無法復原。\n\n重要提醒：確認之後，請關閉此選單，讓遊戲實際運行片刻，然後再存檔。清理會在下一個模擬步驟才發生，因此在暫停狀態下存檔，只會把你的城市原封不動地存下來。\n\n要繼續嗎？", ["opt.CleanUninstall.D"]="一次性的清理，用於乾淨地解除安裝。會將每一條路線還原為原版狀態（釋放被保留的公車、還原去群聚係數、取消模組設定的車輛數量），並從本城市移除模組儲存的資料（你的各路線時刻表、自訂尖峰與實測行駛時間）。按下此鍵後，讓遊戲實際運行片刻（清理會在下一個模擬步驟才發生，因此遊戲暫停時什麼都不會發生），然後務必存檔 —— 在那之後即可移除模組，不會留下任何殘留資料。由於它會清除你的時刻表，所以會先要求確認。就算模組仍安裝著就按下也無妨 —— 路線只會回到單純的原版狀態。", ["opt.MaxDwellRoad.L"]="最長停靠時間 —— 公車（發車時刻之後的分鐘數）", ["opt.MaxDwellRoad.D"]="一輛公車在它張貼的發車時刻之後，最多還能為那些已經正在上車的乘客多等多久。這是上限，不是目標：沒有人上車的公車仍會準時在張貼的那一分鐘發車，這項設定絕不會讓它多延遲一秒。它之所以存在，是因為原版遊戲從某人開始走向車輛的那一刻起，就把他算成乘客了，因此若強制發車，所有還在穿過候車區走向車輛的人都會被推回等候隊伍。現在車輛會等他們，但等候時間絕不會超過這個上限。預設為 3 分鐘。設為 0 表示準點發車、不等任何人。注意：它的作法是縮短原版遊戲本身允許的上車時間，因此它絕不可能讓車輛等得比遊戲原本更久 —— 而且如果你使用會延長遊戲內一天長度的模組，這裡最高的幾個數值可能無法達到。", ["opt.MaxDwellRail.L"]="最長停靠時間 —— 火車、地鐵與路面電車（發車時刻之後的分鐘數）", ["opt.MaxDwellRail.D"]="軌道運輸的相同上限，預設同樣是 3 分鐘。如果你看到繁忙月台上的人越積越多，就把它調高：火車或地鐵要讓滿滿一整個月台的人上下車，所花的時間遠比公車長，乘客會沿著月台分散，各自走向自己的車廂，而且不像公車，它永遠無法跳過任何一站。請記得這項寬限適用於每一站，因此在長路線上給得太寬鬆，繞行一圈累積下來會相當可觀 —— 而且停靠時間越長，實際環行時間也越長，路線為了維持同樣的發車間隔就會需要更多車輛。與公車的數值一樣，它是縮短原版遊戲本身允許的上車時間，而不是延長它，因此在慢速時間模組之下，最高的幾個數值可能無法達到。", ["opt.RealisticTravelTime.L"]="真實旅行時間（校正發車時刻表）", ["opt.RealisticTravelTime.D"]="遊戲本身對一條路線所需時間的估算，低估了真實模擬的環線 —— 公車在每一站都要加速與煞車，而估算忽略了這一點（實測站點稀疏的路線約為 1.7 倍，站點密集的路線最高可達約 2.5 倍）。開啟此選項後，模組會實測每條路線的真實環線時間，並張貼真實的靠站時刻，讓時刻表符合公車實際的運行情況。不花任何費用 —— 它只是讓時鐘變得誠實。預設為關閉；在你啟用之前，既有的時刻表維持不變。", ["opt.ProvisionRealFleet.L"]="根據實際行駛時間配置車隊（增加車輛數量）", ["opt.ProvisionRealFleet.D"]="同時依每條路線的「真實」環線時間（而非估算值）來配置車輛數。這是會花錢的選項：要在真實環線約為估算 2 倍的路線上維持緊密班距，需要約兩倍的車輛，也需要兩倍的維護費。關閉（預設）維持以估算為準的車輛數，因此路線實際運行的有效班距會悄悄比你設定的更長；開啟則按真實環線配置。只增不減 —— 絕不會把某條路線的車輛降到估算值以下 —— 並設有上限，因此一次錯誤的讀數不會讓你被公車淹沒。", ["ui.vehNotOnTimetable"]="尚未加入時刻表。車輛首次抵達終點站時才會取得時刻表。", ["ui.vehHolding"]="在此等候至 {at} 的預定發車時間。", ["ui.vehAtStopLate"]="停靠此站，比 {at} 的發車時間晚 {n} 分鐘。", ["ui.vehAtStop"]="停靠此站，將於 {at} 發車。", ["ui.vehNextStop"]="下一站預定時間為 {at}。", ["ui.vehBehind"]="誤點 {n} 分鐘。下一站原定時間為 {at}。", ["ui.vehRefining"]="此路線仍在測量實際環行時間，因此這些時間會有變動。", ["ui.rttOffWarning"]="真實旅行時間已關閉，因此顯示的時間使用遊戲本身的估算，而非測得的環行時間。請在模組選項中開啟以使用實測時間。", ["ui.loopMeasuring"]="正在測量實際環行時間（已完成 {laps}/{need} 圈）。", ["ui.loopRefining"]="實際環行時間約 {real} 分鐘，仍在校準（已完成 {wlaps}/{need2} 圈）。", ["ui.loopMeasured"]="實際環行時間為 {real} 分鐘，已測得（為 {est} 分鐘估算值的 {corr} 倍）。", ["ui.countMayRise"]="該數量為保守估計，測量完成後可能增加。", ["ui.sizingSoon"]="待該路線的時長估算穩定後即會配置車輛。", ["ui.notSetByMod"]="該發車間隔需要約 {n} 輛車。本模組不設定車輛數量。", ["ui.provisioning"]="為此配置約 {n} 輛車。", ["ui.realLoopEstimated"]="實際一圈約 {real} 分鐘（是 {est} 分鐘估算值的 {corr} 倍，估算）。", ["ui.realLoopMeasured"]="實際一圈約 {real} 分鐘（是 {est} 分鐘估算值的 {corr} 倍，實測）。", ["enum.VehicleCounts.HandsOff"]="不讓模組決定", ["enum.VehicleCounts.ModDecides"]="讓模組決定", ["ui.noticeAsk"]="要重新開啟真實時間嗎？顯示時間將與實際路線一致，路線的車輛數量也可能隨之增加。", ["opt.VehicleCounts.L"]="車輛數量", ["opt.VehicleCounts.D"]="由誰決定每條已設定時刻表的路線運行多少車輛。「讓模組決定」（建議）透過測量路線實際跑完一圈需要多久來配置車輛，使其能夠維持你設定的發車間隔，無需額外關注。在此模式下，模組會掌管所有已設定時刻表路線的車輛數量：遊戲內建的指派車輛滑桿不會保留，因為模組會重新套用自己的數值。「不讓模組決定」會交還所有路線，此後不再改動車輛數量，方便你自己或專門的車隊模組接管。兩種模式下的發車等待行為完全相同。如果某條路線所需的車輛超出你的預期，請調寬該路線的發車間隔，那才是真正的調節手段。", ["ui.noticeTitle"]="真實時間設定已關閉", ["ui.noticeBody"]="先前本模組一律會測量每條路線的實際行駛時間，並將其用於顯示時間與車輛數量。現在兩者為獨立設定，且預設皆為關閉，因此本城市使用的是遊戲本身的估算值。", ["ui.noticeWhere"]="你可以隨時在選項的「真實性」中變更。", ["ui.noticeKeep"]="開啟", ["ui.noticeOff"]="保持關閉", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使空無一人）", ["opt.StopAtEveryStop.D"]="預設情況下，《Cities: Skylines II》允許公車「跳過」某個既無人等車、也無人下車的站點 —— 它只會減速滑行通過，因此該站不會被保留到其排定的發車時刻，公車便可能領先於時刻表。無論此設定為何，終點站現在一律強制停靠（跳過終點站會使整份時刻表脫節）。開啟此選項可強制公車在有時刻表路線的「每一站」都靠站停車，讓每一個張貼的時刻都被遵守 —— 代價是在每個空站短暫停留，使路線略微變慢。僅影響公車及其他道路車輛；火車、路面電車、船隻與飛機本來就每站皆停。預設為關閉。", ["opt.RealisticTripsCompat.L"]="Realistic Trips／慢速時間相容性 —— 若你使用 RT 或 Time2Work 請開啟（ALPHA）", ["opt.RealisticTripsCompat.D"]="預設為關閉 —— 除非你使用會延長遊戲內一天長度的模組（Time2Work／「Realistic Trips」或類似模組），否則請保持關閉。搭配這類模組時開啟，發車時刻、靠站時刻與車隊規模便會維持正確而不會提早運行；模組會自動實測真實的一天長度。若沒有慢速時間模組，此設定不會有任何作用；而若模組偵測到有這類模組但此設定為關閉，它會在日誌中註記。注意：此相容路徑仍為 ALPHA，尚未在遊戲中對 Realistic Trips 進行測試 —— 若有任何異常請回報。在 Realistic Trips 下，你的路線會正確地使用比以往更少的車輛。", ["opt.MorningPeakStart.L"]="早尖峰開始", ["opt.MorningPeakStart.D"]="早尖峰服務等級開始的時刻。", ["opt.MorningPeakEnd.L"]="早尖峰結束", ["opt.MorningPeakEnd.D"]="早尖峰服務等級結束的時刻。", ["opt.EveningPeakStart.L"]="晚尖峰開始", ["opt.EveningPeakStart.D"]="晚尖峰服務等級開始的時刻。", ["opt.EveningPeakEnd.L"]="晚尖峰結束", ["opt.EveningPeakEnd.D"]="晚尖峰服務等級結束的時刻。", ["opt.NightStart.L"]="夜間開始", ["opt.NightStart.D"]="夜間服務開始的時刻（可能跨越午夜）。", ["opt.NightEnd.L"]="夜間結束", ["opt.NightEnd.D"]="夜間服務結束的時刻。", ["opt.Enabled.L"]="啟用 TransitTimetables", ["opt.Enabled.D"]="整個模組的總開關。關閉＝完全回到原版：每條路線都不再受管理（任何被保留的公車會被釋放，模組套用的車輛數與去群聚係數都會還原），同時保留你的各路線時刻表，以便重新啟用時可繼續使用。預設為開啟。", ["grp.GroupWindows"]="尖峰時段", ["grp.GroupCompat"]="相容性", ["grp.GroupStops"]="站點", ["grp.GroupGeneral"]="一般", ["ui.to"]="至", ["ui.timetable"]="時刻表", ["ui.on"]="開啟", ["ui.off"]="關閉", ["ui.ttNow"]="目前每 {i} 分鐘 · {f} 輛車", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班發車", ["ui.peakInterval"]="尖峰", ["ui.offPeakInterval"]="離峰", ["ui.otherHours"]="其他時段", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="自訂尖峰（此路線）", ["ui.morningPeak"]="早尖峰", ["ui.eveningPeak"]="晚尖峰", ["ui.customPeakInterval"]="自訂尖峰班距", ["ui.terminusHint"]="選擇一個站點以檢視其發車時刻，並將其設為此路線的終點站。", ["ui.noLines"]="沒有路線行經此站。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終點站", ["ui.departs"]="發車：{d}", ["ui.noDepartures"]="無排定發車", ["ui.notTimetabled"]="無時刻表", ["ui.estimatedTimes"]="預估值，尚未實測", ["ui.setTerminusThis"]="設為終點站", ["ui.setTerminusAll"]="設為此處所有路線的終點站", ["ui.setTerminusHint"]="終點站是時刻表與車輛保留的錨點；公車在此退役。", ["ui.buttonTooltip"]="運輸時刻表", ["ui.panelTitle"]="發車時刻", ["ui.panelHint"]="選擇一個站點以檢視每條路線由此站發車的時刻。要編輯某條路線的時刻表，請選取該路線 —— 其控制項位於該路線的資訊面板中。", },
        };
    }
}
